/* ===================== DYBDETRENING — 100 spørsmål, nivå 1-4 =====================
   Selvrettet spørsmål-og-svar-bank med økende vanskelighetsgrad, tungt vektet mot
   Oppgave 3 (kort sikt/AS-AD/IS-MP/åpen økonomi). Filtrerbar på nivå og tema, med
   "kunne/må øve"-vurdering som lagres lokalt og mater repetisjonsmotoren. */
window.SAM3 = window.SAM3 || {};
window.SAM3_DATA = window.SAM3_DATA || {};
window.SAM3_DATA.dybde = {"cats":["AS-AD","Eksamensteknikk","IS-kurven","Kort sikt – grunnlag","Lang sikt (vekst/inflasjon)","Myndigheter / forventninger","Nasjonalregnskap","Pengepolitikk / MP","Phillips / AS","Åpen økonomi / Norge"],"lvl":{"1":["Nivå 1","Grunnbegreper — definisjoner, ligninger og symboler"],"2":["Nivå 2","Mekanismer — hvorfor virker sammenhengene?"],"3":["Nivå 3","Sjokkanalyse — skift, dynamikk og regning"],"4":["Nivå 4","Eksamensnivå — utledning, integrasjon og politikkanbefaling"]},"items":[{"n":1,"k":"Kort sikt – grunnlag","s":"Hva er produksjonsgapet? Skriv formelen og forklar tolkningen.","f":"Ỹₜ = (Yₜ − Ȳₜ)/Ȳₜ — det <b>prosentvise<\/b> avviket mellom faktisk BNP (Yₜ) og potensielt BNP (Ȳₜ).<br><br><b>Tolkning:<\/b> Positivt gap = høykonjunktur, kapasiteten presses, inflasjonspress. Negativt gap = lavkonjunktur/resesjon, ledig kapasitet, ledighet over naturlig nivå.<br><br><b>Merk:<\/b> Det er prosentvis — du må dele på Ȳ. Y = 980, Ȳ = 1000 gir −2 %, ikke −20.","id":0},{"n":1,"k":"Kort sikt – grunnlag","s":"Hva er potensielt BNP (Ȳ), og hva bestemmer det?","f":"Det produksjonsnivået økonomien kan holde <b>bærekraftig<\/b> med normal utnyttelse av kapital og arbeidskraft.<br><br>Bestemmes av <b>langsiktsmodellen<\/b>: Ȳ = Ā·K̄^α·L̄^(1−α) — altså teknologi/TFP, kapitalbeholdning og arbeidsstyrke. På kort sikt tas disse som <b>eksogene<\/b> (derav strekene).<br><br><b>Viktig nyanse:<\/b> Ȳ kan ikke observeres direkte — det må estimeres (f.eks. HP-filter). Å forveksle et fall i <i>potensial<\/i> med et konjunkturelt <i>gap<\/i> var en av hovedfeilene bak 1970-tallets pengepolitikk.","id":1},{"n":1,"k":"IS-kurven","s":"Skriv IS-kurven og forklar hvert symbol.","f":"<b>Ỹₜ = ā − b̄(Rₜ − r̄)<\/b><br><br>• <b>Ỹₜ<\/b> = produksjonsgapet (endogen)<br>• <b>ā<\/b> = aggregert etterspørselssjokk — summen av avvik i C-, I-, G- og NX-andelene. Null i likevekt.<br>• <b>b̄<\/b> = rentefølsomheten i etterspørselen (helningsparameter)<br>• <b>Rₜ<\/b> = kortsiktig realrente (endogen, settes via MP)<br>• <b>r̄<\/b> = langsiktig realrente = kapitalens marginalprodukt (MPK), eksogen<br><br>Når Rₜ = r̄ og ā = 0 er Ỹₜ = 0.","id":2},{"n":1,"k":"Pengepolitikk / MP","s":"Skriv MP-kurven (Taylor-regelen) og forklar symbolene.","f":"<b>Rₜ = m̄(πₜ − π̄) + r̄<\/b><br><br>• <b>Rₜ<\/b> = realrenten sentralbanken sikter mot<br>• <b>m̄<\/b> = hvor kraftig sentralbanken reagerer på inflasjonsavvik<br>• <b>πₜ − π̄<\/b> = avvik fra inflasjonsmålet<br>• <b>π̄<\/b> = inflasjonsmålet (2 % i Norge)<br>• <b>r̄<\/b> = langsiktig realrente<br><br><b>Tolkning:<\/b> Inflasjon over målet ⇒ realrenten settes over r̄ (innstrammende). På målet ⇒ Rₜ = r̄. I IS-MP-diagrammet tegnes den som en <b>horisontal linje<\/b> ved valgt R.","id":3},{"n":1,"k":"Phillips / AS","s":"Skriv Phillips-kurven (både generell og adaptiv form).","f":"<b>Generell:<\/b> πₜ = πₜᵉ + v̄·Ỹₜ + ō<br><b>Adaptiv (den vi bruker):<\/b> πₜ = πₜ₋₁ + v̄·Ỹₜ + ō<br><br>• <b>πₜᵉ<\/b> = forventet inflasjon; under adaptive forventninger πₜᵉ = πₜ₋₁<br>• <b>v̄<\/b> = hvor kraftig produksjonsgapet slår ut i prisvekst<br>• <b>ō<\/b> = eksogent prissjokk (kostnadssjokk), null i likevekt<br><br>Omskrevet: <b>Δπₜ = v̄·Ỹₜ + ō<\/b> — <i>endringen<\/i> i inflasjon drives av gapet og prissjokk.","id":4},{"n":1,"k":"AS-AD","s":"Skriv AD-kurven og AS-kurven.","f":"<b>AD: Ỹₜ = ā − b̄m̄(πₜ − π̄)<\/b> (fås ved å sette MP inn i IS)<br><b>AS: πₜ = πₜ₋₁ + v̄·Ỹₜ + ō<\/b> (identisk med Phillips-kurven)<br><br>To ligninger i to ukjente (πₜ, Ỹₜ) ⇒ modellen er determinert.<br><br><b>Akser:<\/b> inflasjon πₜ vertikalt, produksjonsgap Ỹₜ horisontalt. AD heller nedover, AS oppover.","id":5},{"n":1,"k":"AS-AD","s":"Hva kjennetegner likevekt i AS-AD? Nevn alle betingelsene.","f":"<b>Betingelser:<\/b> ingen sjokk (ā = 0 og ō = 0) og konstant inflasjon (πₜ = πₜ₋₁).<br><br><b>Resultat:<\/b><br>• <b>Ỹ* = 0<\/b> — produksjonsgapet er lukket, faktisk BNP = potensielt BNP<br>• <b>π* = π̄<\/b> — inflasjonen er på målet<br>• <b>R* = r̄<\/b> — realrenten er på sitt naturlige nivå<br><br>Dette er punktet økonomien alltid trekkes tilbake mot etter et sjokk.","id":6},{"n":1,"k":"Kort sikt – grunnlag","s":"Skriv Okuns lov og forklar koeffisienten.","f":"<b>u − ū = −0,5 · Ỹ<\/b><br><br>• <b>u − ū<\/b> = syklisk (konjunktur-)ledighet — faktisk minus naturlig ledighet<br>• <b>−0,5<\/b> = for hvert prosentpoeng produksjonen ligger <i>under<\/i> potensial, ligger ledigheten ca. et <b>halvt<\/b> prosentpoeng <i>over<\/i> naturlig nivå<br><br><b>Fortegnet er negativt<\/b> fordi produksjon og ledighet beveger seg motsatt: svak økonomi ⇒ høy ledighet. Loven er broen mellom produksjonsgapet og arbeidsmarkedet.","id":7},{"n":1,"k":"Pengepolitikk / MP","s":"Skriv Fisher-ligningen og forklar hvorfor den er sentral på kort sikt.","f":"<b>Rₜ = iₜ − πₜ<\/b> (realrente = nominell rente − inflasjon)<br><br><b>Hvorfor sentral:<\/b> Sentralbanken styrer den <b>nominelle<\/b> renten iₜ direkte, men det er <b>realrenten<\/b> Rₜ som påvirker økonomien via IS. Fordi inflasjonen er <b>treg<\/b> på kort sikt, følger Rₜ med når iₜ endres — det er derfor pengepolitikken virker.","id":8},{"n":1,"k":"Kort sikt – grunnlag","s":"Hva er adaptive forventninger, og hvordan skrives de?","f":"<b>πₜᵉ = πₜ₋₁<\/b> — folk forventer at inflasjonen neste periode blir som forrige periode. De ser <b>bakover<\/b>.<br><br>Begrunnelse: forventninger er empirisk persistente, og prissettere/lønnsforhandlere legger stor vekt på historisk inflasjon.<br><br><b>Konsekvens:<\/b> AS-kurven henger igjen etter et sjokk og kan bare flytte seg gradvis — dette er <b>driveren av all overgangsdynamikk<\/b> i AS-AD.","id":9},{"n":1,"k":"Kort sikt – grunnlag","s":"Hva er stagflasjon, og hvilket sjokk gir det?","f":"<b>Stagflasjon<\/b> = høy inflasjon <i>og<\/i> stagnerende/fallende produksjon samtidig.<br><br>Skyldes et <b>positivt prissjokk (ō > 0)<\/b> — et kostnadssjokk som skifter <b>AS opp<\/b>. Sentralbanken hever renten som respons, og vi får en bevegelse <i>langs AD<\/i>: høyere π og lavere Ỹ.<br><br><b>Historisk eksempel:<\/b> oljeprissjokkene i 1974 og 1979.","id":10},{"n":1,"k":"Åpen økonomi / Norge","s":"Hva er den norske valutakurskonvensjonen? Pass på fortegnet.","f":"<b>ε = NOK per enhet utenlandsk valuta<\/b> (f.eks. NOK/€ eller NOK/$).<br><br>• <b>ε ↑ = SVAKERE krone<\/b> (depresiering — flere kroner per euro)<br>• <b>ε ↓ = STERKERE krone<\/b> (appresiering)<br><br>Dette er <b>motsatt<\/b> av internasjonal indekskonvensjon, og en klassisk fortegnsfelle. <b>Råd:<\/b> skriv alltid eksplisitt «kronen styrkes/svekkes» i tillegg til ε-notasjonen.","id":11},{"n":1,"k":"Åpen økonomi / Norge","s":"Hva er I-44?","f":"Den <b>importvektede effektive kroneindeksen<\/b> — kronens verdi målt mot en kurv av Norges 44 viktigste handelspartneres valutaer, vektet etter importandeler.<br><br>Norges Banks hovedmål på kronekursen. Gir et bedre bilde enn én enkelt bilateral kurs (som NOK/€).","id":12},{"n":1,"k":"Åpen økonomi / Norge","s":"Hva er Norges Banks mandat, og hva betyr «over tid»?","f":"Forskrift av 02.03.2018: operativt mål er årsvekst i konsumprisene <b>«over tid» nær 2 %<\/b>. Styringen skal være <b>fremoverskuende og fleksibel<\/b>, og også bidra til <b>høy og stabil produksjon og sysselsetting<\/b> samt motvirke <b>finansielle ubalanser<\/b>.<br><br><b>«Over tid» er nøkkelen:<\/b> det gir <b>fleksibel inflasjonsstyring<\/b> — Bernankes «constrained discretion». Norges Bank kan reagere på kortsiktige forstyrrelser, men er forpliktet til målet på sikt. Derfor følger den <i>ikke<\/i> en mekanisk Taylor-regel.","id":13},{"n":1,"k":"Nasjonalregnskap","s":"Skriv generalbudsjettligningen og forklar leddene.","f":"<b>Y = C + I + G + NX<\/b><br><br>• <b>C<\/b> = privat konsum<br>• <b>I<\/b> = private + offentlige realinvesteringer<br>• <b>G<\/b> = offentlig konsum<br>• <b>NX<\/b> = nettoeksport = eksport − import<br><br>Dette er utgiftssiden av BNP. De to andre er produksjonssiden (sum verdiskaping) og inntektssiden (lønn + kapitalavkastning). Alle tre gir <b>samme tall<\/b>.","id":14},{"n":1,"k":"Nasjonalregnskap","s":"Hva er sparebalansen, og hva er driftsbalansen?","f":"<b>S = I + CA<\/b> der <b>CA = NX + F<\/b><br><br>• <b>S<\/b> = bruttosparing = BNI − C − G<br>• <b>CA<\/b> = driftsbalansen (current account)<br>• <b>F<\/b> = netto faktorinntekt fra utlandet (stor og positiv for Norge pga. oljefondet)<br><br><b>Tolkning:<\/b> Sparing brukes enten til realinvestering hjemme (I) eller til netto utlån til utlandet (CA). Overskudd på CA = landet bygger opp fordringer på utlandet.","id":15},{"n":1,"k":"Lang sikt (vekst/inflasjon)","s":"Skriv Cobb-Douglas-funksjonen og de tre egenskapene.","f":"<b>Y = A·K^α·L^(1−α)<\/b> med α = 1/3<br><br><b>Tre egenskaper:<\/b><br>1. Positiv grenseproduktivitet: MPK > 0, MPL > 0<br>2. <b>Avtakende<\/b> grenseproduktivitet i hver faktor<br>3. <b>Konstant skalautbytte<\/b> (CRS) — dobler du både K og L, dobles Y<br><br>A = total faktorproduktivitet (TFP): teknologi, kunnskap, institusjoner, organisering.","id":16},{"n":1,"k":"Lang sikt (vekst/inflasjon)","s":"Skriv Solows kapitalakkumulasjonsligning og steady state.","f":"<b>Δk = s·y − d·k<\/b> med <b>y = A·k^α<\/b><br><br>Kapitalen vokser når sparing/investering (sy) overstiger depresiering (dk).<br><br><b>Steady state (Δk = 0):<\/b> sy = dk gir<br><b>k* = (sA/d)^(1/(1−α))<\/b> og <b>y* = A^(3/2)·(s/d)^(1/2)<\/b> med α = 1/3.<br><br>Med befolkningsvekst: k* = (sA/(n+d))^(1/(1−α)).","id":17},{"n":1,"k":"Lang sikt (vekst/inflasjon)","s":"Hva er den langsiktige vekstraten i Romer-modellen?","f":"<b>g*_y = γ·n<\/b><br><br>Bare <b>befolkningsveksten n<\/b> og <b>idéparameteren γ<\/b> påvirker vekstRATEN på balansert vekstbane.<br><br><b>Kritisk skille:<\/b> endringer i forskerandelen ℓ̄ eller forskningsproduktiviteten z̄ gir bare <b>NIVÅeffekter<\/b> — midlertidig raskere vekst opp til en høyere bane, men samme helning etterpå.","id":18},{"n":1,"k":"Lang sikt (vekst/inflasjon)","s":"Skriv badekarmodellen og den naturlige ledighetsraten.","f":"<b>ΔUₜ₊₁ = s·Eₜ − f·Uₜ<\/b> med Eₜ + Uₜ = L<br><br>• <b>s<\/b> = separasjonsrate (andel sysselsatte som mister jobben, ~1–2 %)<br>• <b>f<\/b> = jobbfinnerate (andel ledige som finner jobb, ~20 %)<br><br><b>Steady state:<\/b> <b>u* = s/(f + s)<\/b><br><br>Eks.: s = 2 %, f = 18 % ⇒ u* = 0,02/0,20 = 10 %. Merk at L faller ut — raten avhenger bare av strømningsratene.","id":19},{"n":1,"k":"Lang sikt (vekst/inflasjon)","s":"Skriv kvantitetsteorien og resultatet for inflasjon på lang sikt.","f":"<b>M·V = P·Y<\/b> (kvantitetsligningen — en identitet)<br><br>Med tre antakelser (klassisk dikotomi: Y = Ȳ; konstant V; eksogen M) og vekstrateregelen:<br><b>gM + gV = gP + gY<\/b>, og med gV = 0:<br><br><b>π* = gM − gY<\/b><br><br>Pengevekst utover BNP-vekst slår <b>én-til-én<\/b> ut i inflasjon på lang sikt. «Inflation is always and everywhere a monetary phenomenon» (Friedman).","id":20},{"n":1,"k":"Kort sikt – grunnlag","s":"Hva er KPI og KPI-JAE, og hvorfor bruker Norges Bank sistnevnte?","f":"<b>KPI<\/b> = konsumprisindeksen — prisen på en fast kurv av varer og tjenester.<br><b>KPI-JAE<\/b> = KPI justert for avgiftsendringer og uten energivarer.<br><br><b>Hvorfor JAE:<\/b> den filtrerer bort volatile avgifts- og energipriser og gir dermed et bedre bilde av det <b>underliggende<\/b> inflasjonspresset — mer relevant for rentesettingen enn kortsiktige svingninger i strømpris.","id":21},{"n":1,"k":"IS-kurven","s":"Hva består ā av, og hvorfor er ā = 0 i langsiktig likevekt?","f":"<b>ā = āc + āi + āg + (āex − āim) − 1<\/b><br><br>Det er summen av de eksogene etterspørselsandelene (konsum, investering, offentlig, nettoeksport), minus 1.<br><br><b>Hvorfor 0 i likevekt:<\/b> I langsiktig likevekt summerer andelene til nøyaktig 1 — det følger av nasjonalregnskapsidentiteten Y = C + I + G + NX. Altså āc + āi + āg + (āex − āim) = 1, som gir ā = 0.<br><br><b>Men på kort sikt<\/b> kan andelene avvike fra sine normalnivåer — og det er nettopp et <b>etterspørselssjokk<\/b> (ā ≠ 0).","id":22},{"n":1,"k":"Phillips / AS","s":"Hva er forskjellen på Phillips-kurven og AS-kurven?","f":"<b>Ingen — de er identiske.<\/b><br><br>AS-kurven i AS-AD-modellen <i>er<\/i> Phillips-kurven på adaptiv form:<br><b>πₜ = πₜ₋₁ + v̄·Ỹₜ + ō<\/b><br><br>Navnene brukes om hverandre: «Phillips-kurven» når vi snakker om sammenhengen mellom produksjon/ledighet og inflasjon, «AS-kurven» (aggregert tilbud) når vi setter den sammen med AD i ett diagram.<br><br><b>Merk:<\/b> Den <i>opprinnelige<\/i> Phillips-kurven (1958) koblet lønnsvekst til <b>ledighet<\/b>. Via Okuns lov er det samme relasjon, siden ledighet og produksjonsgap henger sammen.","id":23},{"n":1,"k":"Kort sikt – grunnlag","s":"Hva er forskjellen på eksogene og endogene variabler? Gi eksempler fra kortsiktsmodellen.","f":"<b>Eksogene<\/b> = bestemmes <i>utenfor<\/i> modellen, tas som gitt. Markeres i Jones med <b>strek over<\/b>.<br><i>Eksempler:<\/i> ā, b̄, m̄, v̄, ō, r̄, π̄, Ȳ<br><br><b>Endogene<\/b> = bestemmes <i>av<\/i> modellen, det vi løser for.<br><i>Eksempler:<\/i> Ỹₜ, Rₜ, πₜ<br><br><b>Hvorfor det betyr noe på eksamen:<\/b> Et «sjokk» er alltid en endring i en <b>eksogen<\/b> variabel. Når du skal avgjøre om en kurve skifter, spør: endres en eksogen parameter (⇒ skift), eller er det en endogen variabel som står på aksen (⇒ bevegelse langs)?","id":24},{"n":1,"k":"Nasjonalregnskap","s":"Hva er forskjellen på BNP og BNI, og hvorfor er skillet viktig for Norge?","f":"<b>BNI = BNP + F<\/b>, der F = netto faktorinntekt fra utlandet (renter, utbytte, lønn opptjent i utlandet minus tilsvarende ut).<br><br>• <b>BNP<\/b> = verdiskaping <i>innenfor landets grenser<\/i><br>• <b>BNI<\/b> = inntekt som <i>tilfaller landets innbyggere<\/i><br><br><b>Hvorfor viktig for Norge:<\/b> Oljefondet (SPU) er investert i utlandet og gir stor avkastning. Denne inngår i <b>F<\/b>, ikke i BNP. Norges BNI er derfor betydelig <b>større<\/b> enn BNP.<br><br>Det er BNI som er relevant for sparing: S = BNI − C − G.","id":25},{"n":1,"k":"Åpen økonomi / Norge","s":"Hva er handlingsregelen?","f":"Regelen om at det <b>strukturelle, oljekorrigerte underskuddet<\/b> på statsbudsjettet over tid skal tilsvare den <b>forventede realavkastningen<\/b> av Statens pensjonsfond utland (SPU/«oljefondet»).<br><br><b>Hensikt:<\/b> å bruke oljeinntektene på en bærekraftig måte — man bruker avkastningen, ikke selve fondskapitalen, slik at også fremtidige generasjoner får glede av den.<br><br><b>Stabiliseringsegenskap:<\/b> Regelen gjelder <i>over tid<\/i>, så den tillater <b>motsyklisk<\/b> bruk — man kan bruke mer i nedgangstider (som under korona) og mindre i oppgangstider.","id":26},{"n":2,"k":"IS-kurven","s":"Hvorfor heller IS-kurven nedover? Gi den fulle mekanismen.","f":"Fordi <b>investeringene er rentefølsomme<\/b>.<br><br><b>Mekanisme steg for steg:<\/b> Nettonåverdien av å låne, investere og betale tilbake er <b>(r̄ − Rₜ)<\/b>: avkastningen er kapitalens marginalprodukt r̄, kostnaden er lånerenten Rₜ. Når <b>Rₜ stiger over r̄<\/b> blir færre investeringsprosjekter lønnsomme ⇒ investeringene faller ⇒ samlet etterspørsel faller ⇒ produksjonsgapet faller.<br><br>Konsum trekker i samme retning (dyrere å låne, mer lønnsomt å spare). <b>b̄<\/b> måler styrken i denne sammenhengen.<br><br><b>Dette er hjertet i kortsiktsmodellen:<\/b> renten påvirker realøkonomien gjennom investeringene.","id":27},{"n":2,"k":"AS-AD","s":"Hvorfor heller AD-kurven nedover? (Pass på — det er IKKE vanlig etterspørselslogikk.)","f":"AD er <b>ikke<\/b> en vanlig markedsetterspørselskurve der lavere pris gir høyere etterspurt mengde.<br><br><b>Den korrekte mekanismen går via sentralbanken:<\/b> Når inflasjonen er over målet (πₜ > π̄), hever sentralbanken — etter MP-regelen — realrenten. Høyere realrente demper via IS investeringer og konsum, og produksjonen faller.<br><br>Altså: <b>π ↑ ⇒ R ↑ (MP) ⇒ Ỹ ↓ (IS)<\/b>. AD beskriver hvordan sentralbanken <i>setter<\/i> kortsiktig BNP for hvert inflasjonsnivå.<br><br>Sensor ser spesifikt etter at du nevner <b>sentralbankresponsen<\/b> her — ikke bare «høyere pris, lavere etterspørsel».","id":28},{"n":2,"k":"Phillips / AS","s":"Hvorfor heller AS/Phillips-kurven oppover? Forklar hvert ledd.","f":"<b>πₜ = πₜ₋₁ + v̄·Ỹₜ + ō<\/b><br><br>• <b>πₜ₋₁ (forventninger):<\/b> bedrifter setter priser og ansatte forhandler lønn ut fra forventet inflasjon — forventningene «bakes inn».<br>• <b>v̄·Ỹₜ (etterspørselspress):<\/b> i en <b>boom<\/b> produseres det over normal kapasitet — arbeidskraft og maskiner presses, lønninger bys opp, vedlikehold utsettes. Kostnadene stiger, og bedriftene velter dette over i <b>høyere prisvekst enn den rådende inflasjonen<\/b>. Derfor positiv helning.<br>• <b>ō (prissjokk):<\/b> direkte kostnadssjokk (f.eks. oljepris) løfter inflasjonen uavhengig av etterspørselen.","id":29},{"n":2,"k":"Pengepolitikk / MP","s":"Hvorfor kan sentralbanken styre REALrenten på kort sikt, når den bare setter den nominelle?","f":"Fordi <b>inflasjonen er treg («sticky»)<\/b> på kort sikt.<br><br>Sentralbanken setter iₜ. Siden πₜ ikke rekker å justere seg umiddelbart, flytter realrenten Rₜ = iₜ − πₜ seg omtrent én-til-én med iₜ.<br><br><b>Hvorfor er inflasjonen treg?<\/b> Menykostnader ved prisjustering, imperfekt informasjon, nominelle kontrakter (lønn, husleie), forhandlingskostnader, sosiale normer om «rettferdige» priser, og pengeillusjon.<br><br><b>Konsekvens:<\/b> dette er nettopp bruddet på den klassiske dikotomien — og hele grunnen til at pengepolitikk har reelle effekter på kort sikt.","id":30},{"n":2,"k":"Pengepolitikk / MP","s":"Hva er Taylor-prinsippet, og hva skjer hvis m̄ ≤ 0?","f":"<b>Taylor-prinsippet:<\/b> m̄ > 0 — sentralbanken må heve realrenten når inflasjonen stiger over målet.<br><br><b>Hvis m̄ ≤ 0<\/b> strammer ikke sentralbanken inn (eller den letter) når inflasjonen stiger. Da blir inflasjonen <b>ustabil<\/b> i en selvforsterkende spiral:<br>høyere inflasjon ⇒ lavere realrente ⇒ mer etterspørsel ⇒ positivt produksjonsgap ⇒ enda høyere inflasjon ⇒ …<br><br>Med m̄ > 0 stiger realrenten nok til å dempe avviket, og økonomien vender tilbake til likevekt.","id":31},{"n":2,"k":"IS-kurven","s":"Hvorfor er konsum modellert som andel av POTENSIELT BNP (Cₜ = āc·Ȳₜ) og ikke faktisk BNP?","f":"Fordi husholdningene <b>glatter konsumet<\/b>.<br><br>• <b>Permanentinntektshypotesen<\/b> (Friedman): konsum baseres på permanent/gjennomsnittlig inntekt, ikke løpende.<br>• <b>Livssyklusmodellen<\/b> (Modigliani): konsum baseres på inntekt over hele livsløpet.<br><br><b>Implikasjon:<\/b> bare <b>permanente<\/b> inntektssjokk bør endre konsumet; midlertidige (transitoriske) svingninger spares/lånes bort. Potensielt BNP Ȳ er nettopp det permanente inntektsnivået — derfor knyttes konsumet til Ȳ og ikke til de kortsiktige svingningene i Y.","id":32},{"n":2,"k":"IS-kurven","s":"Hva er multiplikatoreffekten, og endrer den FORMEN på IS-kurven?","f":"<b>Multiplikator:<\/b> i praksis reagerer noen husholdninger på midlertidige sjokk. Modifisert konsum: Cₜ/Ȳₜ = āc + x̄·Ỹₜ med 0 < x̄ < 1. Da forsterkes sjokk: et sjokk øker Ỹ ⇒ øker konsum ⇒ øker Ỹ videre ⇒ …<br><br><b>Nei — den endrer ikke formen.<\/b> Multiplikatoren forsterker bare konstantleddet ā og helningen b̄. IS forblir en rett, fallende linje i (Ỹ, R)-rommet.<br><br>Samme gjelder om investeringene gjøres avhengige av Ỹ (akseleratormekanisme).","id":33},{"n":2,"k":"Lang sikt (vekst/inflasjon)","s":"Hvorfor gir rigide lønninger arbeidsledighet? Forklar med kryssmodellen.","f":"I grunnmodellen med <b>fleksibel<\/b> lønn klarerer arbeidsmarkedet: ved et negativt etterspørselssjokk faller lønna til nytt likevektsnivå, og alle som vil jobbe til den nye lønna, får jobb. <b>Ingen ufrivillig ledighet.<\/b><br><br>Med <b>rigide<\/b> lønninger (fagforeninger, kontrakter, minstelønn, nominell nedadstivhet) kan ikke lønna falle. Etter at etterspørselskurven skifter innover blir w liggende fast på w*. Ved w* vil bedriftene bare ansette L″, mens L* ønsker å jobbe.<br><br><b>Differansen L* − L″ er ufrivillig arbeidsledighet.<\/b><br><br><b>Kjernepoeng:<\/b> rigiditet gjør at sjokk slår ut i <i>kvantum<\/i> (ledighet) i stedet for <i>pris<\/i> (lønn) — samme logikk som gjør at produksjonsgap kan oppstå på kort sikt.","id":34},{"n":2,"k":"AS-AD","s":"Hvorfor er adaptive forventninger «driveren av overgangsdynamikken»? (Sikkert repetisjonsspørsmål.)","f":"Fordi prissettere ser <b>bakover<\/b> (πₜᵉ = πₜ₋₁), henger inflasjonsforventningene — og dermed AS-kurven — igjen etter et sjokk.<br><br>Etter et prissjokk er πₜ₋₁ nå den <i>forhøyede<\/i> inflasjonen. AS kan derfor bare skifte tilbake mot likevekt <b>gradvis<\/b>, én periode av gangen, ettersom forrige periodes inflasjon synker.<br><br><b>Kontrasten som viser poenget:<\/b> med framoverskuende/rasjonelle forventninger og troverdig politikk ville tilpasningen vært <b>momentan<\/b> — ingen langvarig overgang.<br><br>Dette er den viktigste enkeltinnsikten i AS-AD-dynamikken. Knytt den alltid til forventningsdannelsen.","id":35},{"n":2,"k":"Åpen økonomi / Norge","s":"Forklar UIP-mekanismen steg for steg: hva skjer når Norges Bank hever renten?","f":"<b>Udekket renteparitet (UIP)<\/b> er en ikke-arbitrasjebetingelse: forventet avkastning på plassering i ulike valutaer skal være lik.<br><br><b>Steg for steg:<\/b><br>1. Norges Bank setter i høyere enn utenlandske renter (i^W)<br>2. Det blir mer attraktivt å plassere i kroner ⇒ <b>kapital strømmer inn<\/b><br>3. Etterspørselen etter kroner stiger ⇒ <b>kronen styrker seg<\/b> (εₜ ↓ i norsk konvensjon)<br>4. Markedet forventer at renten normaliseres senere ⇒ forventet <b>fremtidig depresiering<\/b> (εₜ₊₁ ↑)<br>5. Nettopp denne forventede svekkelsen utligner renteforskjellen — UIP holder<br><br>Kvalitativt gjelder samme argument for realrente og realvalutakurs: høyere norsk realrente ⇒ <b>real appresiering<\/b> på kort sikt (siden prisnivået er tregt).","id":36},{"n":2,"k":"Åpen økonomi / Norge","s":"Hvorfor virker en renteheving STERKERE i en liten åpen økonomi enn i en lukket?","f":"Fordi det kommer en <b>ekstra kanal<\/b> i tillegg til den vanlige.<br><br>• <b>IS-kanalen (finnes også i lukket økonomi):<\/b> R ↑ ⇒ dyrere å låne ⇒ investeringer og konsum faller<br>• <b>Valutakanalen (kun åpen økonomi):<\/b> R ↑ ⇒ kapitalinnstrømming (UIP) ⇒ kronen styrker seg ⇒ norske eksportvarer blir dyrere ute og import billigere ⇒ <b>nettoeksporten faller<\/b> ⇒ ytterligere fall i samlet etterspørsel<br><br>Begge kanaler trekker i samme retning, så renteøkninger er <b>mer nedkjølende<\/b> i Norge enn en lukket modell skulle tilsi.","id":37},{"n":2,"k":"Myndigheter / forventninger","s":"Hvorfor er deflasjon farlig? Bruk Fisher-ligningen.","f":"Fra <b>R = i − π<\/b>: når π < 0 blir realrenten <b>høyere enn den nominelle<\/b>.<br><br><b>Intuisjon:<\/b> du betaler tilbake lånet med kroner som er verdt <i>mer<\/i> enn da du lånte ⇒ <b>realverdien av gjelden vokser<\/b> ⇒ konsum og investering kveles ⇒ resesjonen forsterkes ⇒ ytterligere prispress nedover. En selvforsterkende spiral.<br><br><b>Ekstra farlig fordi<\/b> sentralbanken ikke kan motvirke det: nominell rente kan ikke settes særlig under null (ZLB), så realrenten blir liggende for høyt. Klassisk eksempel: «Great Depression» på 1930-tallet, da Fed ikke stimulerte.","id":38},{"n":2,"k":"Myndigheter / forventninger","s":"Hva er nullgrensen (ZLB), og hva er en likviditetsfelle?","f":"<b>ZLB (zero lower bound):<\/b> den nominelle renten kan ikke settes (særlig) under null, fordi folk da heller holder kontanter enn å betale for bankinnskudd. Sentralbanken mister dermed sitt vanlige virkemiddel akkurat når den trenger det mest.<br><br><b>Likviditetsfelle:<\/b> situasjonen der nominell rente og korte instrumenter er ~null. Keynes' poeng: myndighetene kan trykke ekstra penger uten effekt, fordi penger og korte statsobligasjoner da er <b>perfekte substitutter<\/b> — folk bare holder pengene.<br><br><b>Empirisk:<\/b> ekstremt ekspansiv politikk hadde liten effekt i Japan og i USA etter finanskrisen. Svaret ble <b>QE<\/b> og andre ekstraordinære tiltak.","id":39},{"n":2,"k":"Myndigheter / forventninger","s":"Hva er inflation bias, og hvordan oppstår det?","f":"<b>Mekanismen (Kydland-Prescott):<\/b> Etter at bedrifter og ansatte har satt priser og lønninger for neste periode, har sentralbanken et <b>insentiv<\/b> til å kjøre ekspansiv politikk for å presse produksjonen opp — den kan «utnytte» den allerede fastlåste inflasjonen.<br><br><b>Men<\/b> aktørene er ikke dumme: de <b>forutser<\/b> dette og bygger høyere inflasjon inn i kontraktene på forhånd.<br><br><b>Resultat:<\/b> <b>høyere inflasjon uten høyere produksjon<\/b> — det verste av begge verdener. Dette er inflation bias.<br><br><b>Løsning:<\/b> sentralbanken må kunne <b>binde<\/b> seg til ikke å utnytte forventningene — en pengepolitisk regel, uavhengighet og et eksplisitt mål er nettopp slike bindinger.","id":40},{"n":2,"k":"Myndigheter / forventninger","s":"Hvorfor er disinflasjon kostbar under adaptive forventninger, men (nesten) gratis under rasjonelle?","f":"<b>Adaptive:<\/b> πₜᵉ = πₜ₋₁. Forventningene henger igjen uansett hva sentralbanken sier. For å få inflasjonen ned må sentralbanken skape et <b>negativt produksjonsgap<\/b> som presser den ned via v̄·Ỹ — altså en resesjon. Dette er Volcker-disinflasjonen: dyp nedgang som prisen for lavere inflasjon.<br><br><b>Rasjonelle + troverdighet:<\/b> folk bruker all tilgjengelig informasjon, inkludert det nye målet π̄′, og setter πₜᵉ = π̄′ direkte.<br>Formelt: Δπ = Δπ̄ + v̄·ΔỸ + Δō. Med ΔỸ = 0 og Δō = 0 blir <b>Δπ = Δπ̄<\/b> — inflasjonen faller med nøyaktig målendringen, <b>uten<\/b> produksjonsfall.<br><br><b>Forutsetning:<\/b> åpenhet fra og tillit til sentralbanken.","id":41},{"n":2,"k":"Åpen økonomi / Norge","s":"Hvorfor rammer seignorage (inflasjonsskatten) nettopp DEM SOM HOLDER PENGER?","f":"<b>Eksempel:<\/b> alle holder 100 000 kr kontant. Staten dobler pengemengden for å finansiere et prosjekt.<br><br>Fra kvantitetsteorien dobles prisnivået på lang sikt. De 100 000 kr hver person allerede holdt, er nå verdt <b>halvparten<\/b> i kjøpekraft.<br><br><b>Denne verdiforringelsen er skatten.<\/b> Den betales av dem som holder penger uten renteavkastning, siden det er deres beholdning som taper realverdi. Staten har i praksis «beskattet» pengeholderne uten å vedta noen skatt.<br><br>Derfor rammer hyperinflasjon særlig dem som er avhengige av kontanter og ikke kan flykte til realaktiva eller utenlandsk valuta.","id":42},{"n":2,"k":"IS-kurven","s":"Hva er automatiske stabilisatorer, og hva er Ricardiansk ekvivalens?","f":"<b>Automatiske stabilisatorer:<\/b> deler av budsjettet som motvirker sjokk <b>uten<\/b> nye vedtak. Arbeidsledighetstrygd utbetales automatisk mer i nedgangstider; skatteinntektene faller. Dette demper fallet i disponibel inntekt og konsum, og reduserer usikkerheten husholdningene står overfor.<br><br><b>Ricardiansk ekvivalens:<\/b> hvis husholdningene forutser at dagens skattekutt (eller underskudd) må finansieres med <b>fremtidige skatteøkninger<\/b>, sparer de kuttet i stedet for å bruke det. Da mister finanspolitikken mye av sin kraft.<br><br>Dette er én av to hovedutfordringer for finanspolitikk — den andre er <b>timing<\/b> (vanskelig å treffe konjunkturen riktig).","id":43},{"n":2,"k":"AS-AD","s":"Hva er finansielle friksjoner, og hvordan endrer de AD-kurven?","f":"Under finansiell uro krever investorer en <b>risikopremie<\/b>. Renten privat sektor faktisk betaler er:<br><b>R = R_ff + f̄<\/b><br>der R_ff er sentralbankens rente og <b>f̄<\/b> er den (eksogene) risikopremien.<br><br>Satt inn i IS gir dette:<br><b>AD: Ỹₜ = ā − b̄f̄ − b̄m̄(πₜ − π̄)<\/b><br><br><b>Effekt:<\/b> en økning i f̄ skifter <b>AD innover<\/b> — akkurat som et negativt etterspørselssjokk — fordi den effektive lånerenten stiger <i>selv om styringsrenten er uendret<\/i>.<br><br>Dette forklarer hvorfor myndighetenes rentekutt under finanskrisen ikke forhindret at private låntakere møtte høyere renter.","id":44},{"n":2,"k":"Lang sikt (vekst/inflasjon)","s":"Hvorfor gir Solow-modellen INGEN langsiktig vekst per innbygger?","f":"På grunn av <b>avtakende grenseavkastning på kapital<\/b>.<br><br>Hver ny enhet kapital gir mindre og mindre ekstra produksjon (α = 1/3), mens <b>slitasjen dk vokser proporsjonalt<\/b> med kapitalbeholdningen. Til slutt går all sparing med til å erstatte slitasje — sy = dk — og nettoinvesteringen blir null.<br><br>I steady state er k konstant, altså er veksten i y null. <b>Kapitalakkumulasjon alene kan ikke drive varig vekst.<\/b><br><br>Dette er motivasjonen for Romer-modellen: varig vekst må komme fra <b>ideer<\/b>, som ikke er underlagt avtakende avkastning på samme måte (ikke-rivalisering ⇒ økende skalautbytte).","id":45},{"n":2,"k":"Lang sikt (vekst/inflasjon)","s":"Hvorfor er nettoeffekten av et oppsigelsesforbud på ledigheten tvetydig?","f":"Fra <b>u* = s/(f + s)<\/b>:<br><br>• Et forbud mot oppsigelser <b>senker s<\/b> direkte (færre mister jobben) ⇒ isolert sett <b>lavere<\/b> u*<br>• <b>Men:<\/b> når bedrifter ikke får sagt opp folk, blir de langt mer tilbakeholdne med å <b>ansette<\/b> (innlåsing er risikabelt) ⇒ <b>f faller også<\/b> ⇒ isolert sett <b>høyere<\/b> u*<br><br>Siden både teller og nevner faller, er <b>nettoeffekten tvetydig<\/b> — og kan godt bli høyere ledighet, særlig i form av <b>lengre ledighetsperioder<\/b> for dem som først er ledige.<br><br><b>Generell lærdom:<\/b> en politikk som ser god ut når man bare ser på én strøm, kan slå feil fordi den også påvirker den andre. Sosiale sikkerhetsnett balanserer alltid <b>forsikring<\/b> mot <b>insentiver<\/b>.","id":46},{"n":2,"k":"Phillips / AS","s":"Hvorfor gir et vedvarende positivt produksjonsgap STIGENDE inflasjon, ikke bare høy inflasjon?","f":"Se på den adaptive formen: <b>Δπₜ = v̄·Ỹₜ + ō<\/b><br><br>Det er <b>endringen<\/b> i inflasjon som avhenger av produksjonsgapet, ikke nivået.<br><br><b>Mekanisme:<\/b> Med Ỹ > 0 hver periode blir Δπ > 0 hver periode. Inflasjonen i periode 1 blir forventningen i periode 2, som legges til et nytt positivt bidrag, som blir forventningen i periode 3 …<br><br>Altså: πₜ = πₜ₋₁ + v̄Ỹ ⇒ π₁ = π₀ + v̄Ỹ, π₂ = π₀ + 2v̄Ỹ, π₃ = π₀ + 3v̄Ỹ …<br><br><b>Inflasjonen akselererer.<\/b> Dette er grunnen til at sentralbanken ikke kan «tolerere» et permanent positivt gap — det er ikke en engangskostnad i form av litt høyere inflasjon, men en stadig stigende inflasjon.<br><br>(Dette er også kjernen i hvorfor troen på en <i>permanent<\/i> inflasjon-ledighet-avveining på 1970-tallet var feil.)","id":47},{"n":2,"k":"IS-kurven","s":"Hva skiller et ETTERSPØRSELSSJOKK fra en RENTEENDRING i IS-diagrammet? Hvorfor er skillet viktig?","f":"<b>Renteendring (Rₜ):<\/b> Renten står på <b>aksen<\/b> ⇒ vi flytter oss <b>LANGS<\/b> en fast IS-kurve. Kurven selv er uendret.<br><br><b>Etterspørselssjokk (ā):<\/b> ā er en <b>eksogen parameter<\/b> i ligningen ⇒ hele kurven <b>SKIFTER<\/b> horisontalt. Ved samme rente får vi et annet produksjonsgap.<br><br><b>Hvorfor skillet er viktig:<\/b><br>1. Det avgjør hva sentralbanken bør gjøre. Ved et negativt etterspørselssjokk (IS skifter inn) bør renten <b>kuttes<\/b> for å flytte MP ned og gjenopprette Ỹ = 0.<br>2. Det er den vanligste feilen på eksamen. Å tegne et «skift av IS» når renten endres viser at man ikke har forstått modellen.<br><br><b>Praktisk test:<\/b> Spør deg om variabelen står på en akse. Gjør den det ⇒ bevegelse langs.","id":48},{"n":2,"k":"AS-AD","s":"Hva bestemmer HELNINGEN på AD-kurven, og hva betyr en flat vs. bratt AD?","f":"Fra <b>Ỹₜ = ā − b̄m̄(πₜ − π̄)<\/b> er helningen bestemt av produktet <b>b̄·m̄<\/b>.<br><br><b>Flat AD (stor b̄m̄):<\/b> Et gitt inflasjonsavvik gir et <b>stort<\/b> utslag i produksjonen. Skyldes enten:<br>• stor <b>b̄<\/b> — økonomien er svært rentefølsom (mye gjeld, mye flytende rente — som i Norge), eller<br>• stor <b>m̄<\/b> — sentralbanken reagerer aggressivt på inflasjonsavvik<br><br><b>Bratt AD (liten b̄m̄):<\/b> Inflasjonsavvik gir lite utslag i produksjonen — lite rentefølsom økonomi eller forsiktig sentralbank.<br><br><b>Implikasjon:<\/b> I en økonomi med flat AD er pengepolitikken et kraftig verktøy — men også et som gir store realøkonomiske kostnader ved innstramming. Det er en del av begrunnelsen for <i>fleksibel<\/i> inflasjonsstyring.","id":49},{"n":2,"k":"Myndigheter / forventninger","s":"Hva er tidskonsistensproblemet? Gi både den generelle ideen og ett økonomisk eksempel.","f":"<b>Generell idé (Kydland-Prescott 1977):<\/b> Et tidskonsistensproblem oppstår når en plan som er optimal <i>i dag<\/i>, ikke lenger er optimal å gjennomføre <i>når tiden kommer<\/i> — og aktørene, som forutser dette, endrer atferd på forhånd.<br><br><i>Hverdagsbilder:<\/i> å slutte å snuse, stå opp tidlig, lese til eksamen. Klassisk: Odyssevs som binder seg til masten for å motstå sirenene.<br><br><b>Økonomisk eksempel 1 — pengepolitikk:<\/b> Etter at lønninger er satt, frister det sentralbanken å kjøre ekspansivt for å presse opp produksjonen. Aktørene forutser det og priser inn høyere inflasjon ⇒ <b>inflation bias<\/b>: høyere inflasjon uten høyere produksjon.<br><br><b>Økonomisk eksempel 2 — investeringer:<\/b> Etter at bedrifter har investert (sunk cost), frister det myndighetene å skattlegge investeringene hardt. Forutser bedriftene dette, investerer de <b>ikke i det hele tatt<\/b>. Løsningen er å <b>binde<\/b> seg via lovverk og forutsigbare rammer — og å <i>demonstrere<\/i> at man holder seg til reglene.<br><br><b>Hovedbudskap:<\/b> Det kan være gunstig å binde seg til en <b>regel<\/b> framfor å handle fritt (diskresjonært) i hver periode.","id":50},{"n":2,"k":"Åpen økonomi / Norge","s":"Hva er «flight-to-safety», og hvorfor virker det som en stabilisator for Norge?","f":"<b>Fenomenet:<\/b> I perioder med global uro flykter kapital til store, likvide og «trygge» valutaer (USD, CHF, EUR). Små valutaer som NOK <b>svekkes<\/b> (ε ↑).<br><br><b>Hvorfor det stabiliserer norsk økonomi — to kanaler:<\/b><br>1. <b>Konkurranseevne:<\/b> Svakere krone gjør norske eksportvarer billigere ute ⇒ nettoeksporten stiger ⇒ AD skifter ut, akkurat når økonomien trenger det.<br>2. <b>Oljefondet:<\/b> SPU er investert i utenlandsk valuta. Når kronen svekkes, blir fondet verdt <b>flere kroner<\/b> ⇒ handlingsregelen gir større kronebeløp å bruke ⇒ større finanspolitiske impulser inn i norsk økonomi.<br><br><b>Konklusjon:<\/b> Mekanismen som isolert sett ser negativ ut (svak krone) fungerer i praksis som en <b>innebygd automatisk stabilisator<\/b> i kriser. Dette er et sterkt argument i drøftinger av om det norske rammeverket er robust.","id":51},{"n":2,"k":"Lang sikt (vekst/inflasjon)","s":"Hvorfor forklarer TFP mer av inntektsforskjellene mellom land enn kapital gjør?","f":"<b>Matematisk grunn:<\/b> I y = A·k^α med <b>α = 1/3<\/b> går kapitalen inn med en <b>lav eksponent<\/b>. Å doble k øker y med bare 2^(1/3) ≈ 26 %. Selv enorme forskjeller i kapital gir derfor moderate inntektsforskjeller.<br><br><b>Økonomisk grunn:<\/b> <b>avtakende avkastning<\/b>. Å legge kapital til et fattig land med lite kapital hjelper mye i starten, men effekten avtar raskt.<br><br><b>Empirisk:<\/b> Dekomponeringen yᵢ/yⱼ = (Aᵢ/Aⱼ)·(kᵢ/kⱼ)^α viser typisk at kapital forklarer ca. <b>1/3<\/b> og TFP ca. <b>2/3<\/b> av inntektsgapet mellom rike og fattige land.<br><br><b>I Solow blir TFP enda viktigere:<\/b> y* = A^(3/2)(s/d)^(1/2) — eksponenten på A er <b>3/2<\/b>, ikke 1. Grunnen er at høyere A ikke bare øker produksjonen direkte, men også gjør at landet akkumulerer <b>mer kapital<\/b> i steady state. Effekten forsterkes.<br><br><b>Konklusjon:<\/b> Vil man forklare hvorfor Norge er rikere enn Madagaskar, må man forklare forskjeller i <b>teknologi, institusjoner og organisering<\/b> — ikke bare i maskiner.","id":52},{"n":2,"k":"Nasjonalregnskap","s":"Hvorfor gir Laspeyres-indeksen typisk høyere målt vekst enn Paasche?","f":"<b>Mekanismen — substitusjon:<\/b> Varer som blir relativt <b>billigere<\/b> over tid er ofte de som opplever <b>størst volumvekst<\/b> (folk kjøper mer av det som blir billigere — f.eks. elektronikk).<br><br>• <b>Laspeyres<\/b> bruker priser fra <b>begynnelsen<\/b> av perioden. De raskt voksende varene verdsettes da til sine <i>gamle, høye<\/i> priser ⇒ de får <b>stor vekt<\/b> ⇒ høy målt vekst.<br>• <b>Paasche<\/b> bruker priser fra <b>slutten<\/b>. Samme varer verdsettes til sine <i>nye, lave<\/i> priser ⇒ <b>lavere vekt<\/b> ⇒ lavere målt vekst.<br><br><b>Løsningen:<\/b> <b>Fisher-indeksen<\/b> = geometrisk gjennomsnitt av de to. Den brukes i praksis (kjedede indekser) nettopp for å unngå å måtte velge.<br><br><b>Merk:<\/b> samme logikk forklarer hvorfor en fast KPI-kurv over tid kan <b>overvurdere<\/b> inflasjonen — den fanger ikke at folk substituerer bort fra varer som blir dyre.","id":53},{"n":3,"k":"AS-AD","s":"Positivt prissjokk (ō > 0): gjennomfør hele analysen — periode 1 OG videre.","f":"<b>Periode 1:<\/b> Start i likevekt A (Ỹ = 0, π = π̄). Sjokket skifter <b>AS opp<\/b>. Uten produksjonsendring ville inflasjonen steget med hele ō. Men sentralbanken reagerer (MP): høyere inflasjon ⇒ høyere realrente ⇒ bevegelse <b>langs AD<\/b> til punkt B med <b>høyere inflasjon OG lavere produksjon<\/b> = <b>stagflasjon<\/b>.<br><br><b>Periode 2 og framover:<\/b> Sjokket er borte (ō = 0), men vi går ikke rett tilbake til A. Under adaptive forventninger er πₜ₋₁ nå den <i>forhøyede<\/i> inflasjonen fra B. AS skifter derfor bare <b>gradvis nedover<\/b>, periode for periode, ettersom inflasjonsforventningene faller tilbake. Økonomien beveger seg langs AD tilbake mot A.<br><br><b>Nyanse:<\/b> hastigheten tilbake er høyest lengst fra likevekt.<br><br><b>Politikk:<\/b> sentralbanken må holde renten høy inntil forventningene er forankret — kutter den for tidlig, fester inflasjonen seg.","id":54},{"n":3,"k":"AS-AD","s":"Positivt etterspørselssjokk (ā > 0): hvilken kurve skifter, og hvilken bevegelse får vi?","f":"<b>AD skifter ut/høyre.<\/b> (ā inngår i AD-ligningen Ỹ = ā − b̄m̄(π − π̄).)<br><br>Vi får en bevegelse <b>LANGS AS<\/b> til et punkt C med <b>både høyere produksjon og høyere inflasjon<\/b> (Ỹ > 0, π > π̄).<br><br><b>Hvorfor langs AS og ikke skift av AS?<\/b> Fordi AS bare skifter ved endring i ō eller πₜ₋₁ — og i selve sjokkperioden er begge uendret.<br><br><b>Dynamikk:<\/b> C er ikke steady state (π > π̄). Etterspørselssjokk er typisk midlertidige: ā faller tilbake til 0, og økonomien vender tilbake til A. Var sjokket varig, ville den forhøyede πₜ₋₁ etter hvert skiftet AS opp og presset Ỹ tilbake til 0 ved høyere inflasjon.<br><br><b>Eksempler på ā ↑:<\/b> økt optimisme, finanspolitisk ekspansjon, boligboom, sterkere eksportmarkeder.","id":55},{"n":3,"k":"AS-AD","s":"Sentralbanken senker inflasjonsmålet fra 2,5 % til 2,0 %. Hva skjer?","f":"(Dette skjedde faktisk i Norge i 2017.)<br><br><b>1.<\/b> Målet π̄ inngår i AD-kurven ⇒ <b>AD skifter ned/venstre<\/b>. Ved gitt inflasjon krever et lavere mål høyere rente ⇒ lavere produksjon.<br><br><b>2.<\/b> Under <b>adaptive<\/b> forventninger ligger inflasjonen først igjen (πₜ₋₁ er fortsatt høy) ⇒ vi får et <b>midlertidig negativt produksjonsgap<\/b> — en nedgangskonjunktur er prisen for disinflasjonen.<br><br><b>3.<\/b> Etter hvert oppdateres forventningene nedover ⇒ <b>AS skifter også ned<\/b> ⇒ ny likevekt C med π = π̄′ og Ỹ tilbake til 0.<br><br><b>Sentral nyanse:<\/b> hvis forventningene var <b>framoverskuende og det nye målet troverdig<\/b>, ville økonomien nådd C <b>umiddelbart<\/b> — uten kostbar nedgangskonjunktur. Verdien av troverdighet i praksis.","id":56},{"n":3,"k":"AS-AD","s":"Skift eller bevegelse langs? Lag den fullstendige oversikten for IS, MP, AS og AD.","f":"<b>Huskeregel:<\/b> det som står på en <b>akse<\/b> gir bevegelse <i>langs<\/i>; alt annet gir <i>skift<\/i>.<br><br><b>IS<\/b> (akser: Ỹ, R)<br>• Skifter ved: <b>ā<\/b> (etterspørselssjokk), r̄<br>• Bevegelse langs ved: <b>Rₜ<\/b><br><br><b>MP<\/b><br>• Skifter ved: sentralbankens valg av i/R, endring i π̄<br><br><b>AS<\/b> (akser: Ỹ, π)<br>• Skifter ved: <b>ō<\/b> (prissjokk) og <b>πₜ₋₁<\/b> (mellom perioder — dynamikken!)<br>• Bevegelse langs ved: <b>Ỹₜ<\/b><br><br><b>AD<\/b> (akser: Ỹ, π)<br>• Skifter ved: <b>ā<\/b>, <b>π̄<\/b>, <b>f̄<\/b><br>• Bevegelse langs ved: <b>πₜ<\/b><br><br><b>Dette er der flest poeng tapes på eksamen.<\/b> Et etterspørselssjokk skifter AD og gir bevegelse langs AS — aldri omvendt.","id":57},{"n":3,"k":"IS-kurven","s":"Sentralbanken hever den nominelle renten. Vis effekten i IS-MP-diagrammet.","f":"<b>1.<\/b> Siden inflasjonen er treg, gir i ↑ en tilsvarende økning i realrenten: R = i − π stiger.<br><b>2.<\/b> <b>MP-linjen skifter opp<\/b> (høyere valgt realrente).<br><b>3.<\/b> Vi får en bevegelse <b>langs IS<\/b> (renten er på aksen) opp mot venstre.<br><b>4.<\/b> Høyere R ⇒ færre lønnsomme investeringsprosjekter, dyrere lån ⇒ investering og konsum faller.<br><b>5.<\/b> Resultat: <b>negativt produksjonsgap<\/b> (nedkjøling).<br><br><b>Videre:<\/b> via Phillips gir det negative gapet fallende inflasjon (Δπ = v̄·Ỹ < 0), og via Okun stiger ledigheten med ca. 0,5·|Ỹ| prosentpoeng.<br><br><b>Merk kontrasten:<\/b> rentepolitikk flytter <b>MP-linjen<\/b>; etterspørselssjokk flytter <b>IS<\/b>.","id":58},{"n":3,"k":"AS-AD","s":"En finanskrise treffer (boligpriskollaps). Analyser med AS-AD.","f":"<b>To negative impulser samtidig:<\/b><br>1. Redusert boligformue ⇒ lavere konsum og boliginvestering ⇒ <b>ā ↓<\/b> (IS skifter ned)<br>2. Økt usikkerhet ⇒ <b>risikopremien f̄ ↑<\/b><br><br><b>Begge<\/b> skifter <b>AD innover<\/b> (husk AD: Ỹ = ā − b̄f̄ − b̄m̄(π − π̄)) ⇒ <b>dyp nedgangskonjunktur med π < π̄<\/b>.<br><br><b>Politikkrespons:<\/b> sentralbanken kutter renten (MP ned). <b>Men<\/b> hvis renten allerede er lav, treffer man <b>nullgrensen (ZLB)<\/b> — og premien f̄ gjør at private lånerenter forblir høye selv om styringsrenten kuttes.<br><br><b>Dynamikk:<\/b> AS skifter gradvis ned ettersom forventningene oppdateres ⇒ ny likevekt C. Ved et kraftig nok sjokk kan dette innebære <b>deflasjon<\/b> (π < 0), som via Fisher løfter realrenten og forsterker krisen.<br><br><b>Ekstraordinære tiltak:<\/b> QE, samt finanspolitisk ekspansjon.","id":59},{"n":3,"k":"Åpen økonomi / Norge","s":"Trump innfører toll som rammer norsk eksport. Analyser den DUALE effekten.","f":"Ett sjokk med <b>to motsatte<\/b> virkninger — dette er poenget sensor er ute etter (V25 Oppgave 3c):<br><br><b>(1) Negativt AD-sjokk:<\/b> Direkte effekt på norsk eksport kan være begrenset, men indirekte virkninger via globale verdikjeder, svakere handelspartnere og eskalerende proteksjonisme gir lavere etterspørsel etter norske varer ⇒ <b>ā_nx ↓<\/b> ⇒ AD skifter inn.<br><br><b>(2) Negativt AS-sjokk:<\/b> Toll på importerte innsatsvarer øker bedriftenes kostnader ⇒ høyere prispress ⇒ <b>ō ↑<\/b> ⇒ AS skifter opp. Særlig brennbart når inflasjonen allerede er over målet.<br><br><b>Netto:<\/b> Effekten på <b>inflasjon er UKLAR<\/b> (de to drar hver sin vei), mens <b>realøkonomien ventes å falle<\/b> (begge trekker produksjonen ned).<br><br><b>Politikk:<\/b> Ekspansiv <b>finanspolitikk<\/b> kan skifte AD tilbake ut. <b>Pengepolitikken<\/b> bør være mer <b>tilbakeholden<\/b> — rentekutt må vente pga. inflasjonsforventningene — men på sikt, når inflasjonen synker, kan renten settes ned.<br><br><b>Nyanse:<\/b> mer proteksjonisme kan senke <i>potensielt<\/i> BNP, men også faktisk BNP — så produksjonsgapet trenger ikke endres.","id":60},{"n":3,"k":"Åpen økonomi / Norge","s":"Utenlandske renter stiger (f.eks. Fed og ESB strammer inn). Hva skjer med norsk AD?","f":"<b>Mekanisme:<\/b><br>1. Høyere utenlandsk realrente R^W gjør utenlandske plasseringer mer attraktive<br>2. Kapital trekkes ut av Norge ⇒ <b>kronen svekkes<\/b> (εₜ ↑)<br>3. Real depresiering (prisnivået er tregt)<br>4. Norske eksportvarer blir billigere ute, import dyrere ⇒ <b>nettoeksporten stiger<\/b><br>5. <b>Norsk AD skifter UT<\/b> ⇒ positivt produksjonsgap<br><br><b>Konklusjon:<\/b> utenlandske renter virker som et <b>eksogent sjokk i den norske AD-kurven<\/b>. Dette er en av hovedgrunnene til at Norges Bank må følge med på ESB og Fed.<br><br><b>Merk motsatt tilfelle:<\/b> et internasjonalt <b>etterspørselssjokk<\/b> (svakere vekst hos handelspartnere) reduserer eksportetterspørselen ⇒ ā_nx ↓ ⇒ AD skifter inn.","id":61},{"n":3,"k":"Lang sikt (vekst/inflasjon)","s":"Solow: TFP faller permanent (A ↓). Beskriv hele forløpet.","f":"<b>Umiddelbart:<\/b> y = A·k^α faller <b>med en gang<\/b> (A er lavere, k er uendret på kort sikt).<br><br><b>Deretter:<\/b> Fra k* = (sA/d)^(1/(1−α)) ser vi at <b>k* også faller<\/b>. Økonomien ligger nå <i>over<\/i> sitt nye steady state ⇒ sy < dk ⇒ <b>kapitalen bygges ned<\/b> over tid.<br><br><b>Samlet:<\/b> produksjonen fortsetter å falle gradvis mot det nye, lavere steady state. Nedgangen blir altså <b>større på lang sikt enn på kort sikt<\/b> — kapitalnedbyggingen forsterker det opprinnelige fallet.<br><br><b>Kontrast — jordskjelv (k faller, A uendret):<\/b> y faller umiddelbart, men k* er <b>uendret<\/b>. Økonomien ligger nå <i>under<\/i> steady state ⇒ vokser <b>tilbake<\/b> til samme nivå som før. Helt motsatt langsiktig konklusjon!<br><br>Å kunne skille disse to er en klassisk eksamensoppgave (V25 Oppgave 2).","id":62},{"n":3,"k":"Lang sikt (vekst/inflasjon)","s":"Solow: spareraten øker permanent. Hva skjer med y, k og KONSUM over tid?","f":"<b>k:<\/b> sy-kurven skifter opp ⇒ nytt, høyere k*. Kapitalen vokser <b>gradvis<\/b> dit (ikke hopp).<br><br><b>y:<\/b> Følger k oppover — vokser gradvis til nytt, høyere y* = A^(3/2)(s/d)^(1/2). <b>Vekstraten er midlertidig positiv<\/b>, men går tilbake til null i nytt steady state. Dette er en <b>nivåeffekt<\/b>, ikke en varig vekstrateeffekt.<br><br><b>Konsum c = (1−s)y:<\/b> Dette er nøkkelen — <b>konsumet faller FØRST<\/b> (fordi en større andel spares, mens y ennå ikke har rukket å vokse), og <b>stiger deretter<\/b> etter hvert som y vokser.<br><br><b>Viktig forbehold:<\/b> om c ender <i>høyere<\/i> enn før avhenger av om s er under eller over <b>gylden sparerate s_gull = α = 1/3<\/b>. Er s allerede over 1/3, gir mer sparing <b>lavere<\/b> konsum i det nye steady state.","id":63},{"n":3,"k":"Lang sikt (vekst/inflasjon)","s":"Romer: myndighetene øker forskerandelen ℓ̄ permanent. Vekst- eller nivåeffekt?","f":"<b>Nivåeffekt.<\/b><br><br>Fra y*ₜ = C·(z̄ℓ̄N̄)^γ · (1+g)ᵗ med <b>g*_y = γ·n<\/b>:<br><br>• ℓ̄ inngår i <b>konstantleddet<\/b>, ikke i vekstraten<br>• Vi får en periode med <b>midlertidig raskere vekst<\/b> mens økonomien løftes opp til en <b>høyere balansert vekstbane<\/b><br>• Etter overgangen er <b>helningen den samme<\/b> (γn) — bare nivået er permanent høyere<br><br><b>På log-skala:<\/b> banen hopper opp til en parallell, høyere linje.<br><br><b>Bare n̄ eller γ endrer selve vekstraten.<\/b> Dette skillet er en av de aller vanligste eksamensfellene — samme logikk gjelder for z̄ (f.eks. AI som gjør forskning mer produktiv).","id":64},{"n":3,"k":"Lang sikt (vekst/inflasjon)","s":"Romer: fertiliteten faller permanent (n ↓). Hva skjer, og hva kan et lite land gjøre?","f":"<b>Effekt:<\/b> Fra g*_y = γ·n gir lavere n en <b>permanent lavere langsiktig vekstrate<\/b>. Dette er en <b>vekstrateeffekt<\/b> — den mest alvorlige typen, fordi den akkumulerer over tid.<br><br><b>Intuisjon:<\/b> varig idévekst krever varig vekst i antall forskere, som krever befolkningsvekst. Færre mennesker ⇒ færre ideer ⇒ lavere vekst for alle (ideer er ikke-rivaliserende, så alle nyter godt av dem).<br><br><b>Hva kan et lite land gjøre?<\/b><br>• Å øke ℓ̄ (forskerandelen) gir bare en <b>nivåeffekt<\/b> — hjelper, men løser ikke vekstrateproblemet<br>• <b>Det viktigste:<\/b> for et lite land er det <b>globale<\/b> kunnskapslageret som teller. Norsk inntekt avhenger av verdens ideer, ikke bare egne. Åpenhet, handel, deltakelse i internasjonalt forskningssamarbeid og evne til å <b>absorbere<\/b> utenlandsk teknologi er avgjørende.<br><br>(Testet i H25 Oppgave 1.)","id":65},{"n":3,"k":"Lang sikt (vekst/inflasjon)","s":"Regn: s = 3 % og f = 27 %. Finn den naturlige ledighetsraten.","f":"<b>u* = s/(f + s) = 0,03/(0,27 + 0,03) = 0,03/0,30 = 0,10 = 10 %<\/b><br><br><b>Tolkning:<\/b> I steady state er 10 % av arbeidsstyrken ledig. Strømmene balanserer: hver periode mister 3 % av de sysselsatte jobben, og 27 % av de ledige finner jobb.<br><br><b>Sjekk med gjennomsnittlig ledighetsvarighet:<\/b> 1/f = 1/0,27 ≈ 3,7 perioder.<br><br><b>Merk:<\/b> arbeidsstyrken L faller ut av formelen — raten avhenger kun av strømningsratene, ikke av økonomiens størrelse.","id":66},{"n":3,"k":"Kort sikt – grunnlag","s":"Regn: produksjonsgapet er −4 %. Hva blir syklisk ledighet, og hva skjer med inflasjonen?","f":"<b>Okuns lov:<\/b> u − ū = −0,5 · Ỹ = −0,5 · (−4 %) = <b>+2 prosentpoeng<\/b><br>Ledigheten ligger altså 2 prosentpoeng <b>over<\/b> sitt naturlige nivå. Er ū = 4 %, blir faktisk ledighet 6 %.<br><br><b>Phillips-kurven:<\/b> Δπₜ = v̄·Ỹₜ + ō. Med Ỹ = −4 % og f.eks. v̄ = 0,5 (og ō = 0):<br>Δπ = 0,5 · (−4) = <b>−2 prosentpoeng<\/b><br>Inflasjonen <b>faller<\/b> med 2 prosentpoeng fra forrige periode.<br><br><b>Sammenhengen:<\/b> negativt gap ⇒ ledig kapasitet ⇒ mindre kostnadspress ⇒ avtakende inflasjon, samtidig som ledigheten stiger. Dette er den klassiske avveiningen sentralbanken står overfor.","id":67},{"n":3,"k":"Pengepolitikk / MP","s":"Regn: π = 5 %, π̄ = 2 %, r̄ = 2 %, m̄ = 0,5. Finn realrenten og vurder innretningen.","f":"<b>Taylor-regelen:<\/b> R = m̄(π − π̄) + r̄ = 0,5·(5 − 2) + 2 = 0,5·3 + 2 = <b>3,5 %<\/b><br><br><b>Vurdering:<\/b> R = 3,5 % > r̄ = 2 % ⇒ pengepolitikken er <b>innstrammende (kontraktiv)<\/b>. Det er riktig respons når inflasjonen ligger 3 prosentpoeng over målet.<br><br><b>Nominell rente (Fisher):<\/b> i = R + π = 3,5 + 5 = <b>8,5 %<\/b><br><br><b>Videre via IS:<\/b> R over r̄ gir Ỹ = ā − b̄(R − r̄) < 0 (med ā = 0) — altså et negativt produksjonsgap som via Phillips presser inflasjonen ned mot målet. Nøyaktig hensikten.","id":68},{"n":3,"k":"AS-AD","s":"Regn: ā = 0, b̄ = 2, m̄ = 0,5, π̄ = 2 %. Finn produksjonsgapet når π = 6 %.","f":"<b>AD-kurven:<\/b> Ỹ = ā − b̄m̄(π − π̄)<br><br>Ỹ = 0 − 2·0,5·(6 − 2) = −1·4 = <b>−4 %<\/b><br><br><b>Tolkning:<\/b> Med inflasjonen 4 prosentpoeng over målet responderer sentralbanken så kraftig at produksjonen ligger 4 % under potensial.<br><br><b>Sjekk konsistens:<\/b> R = m̄(π − π̄) + r̄ = 0,5·4 + r̄ = r̄ + 2 ⇒ IS gir Ỹ = 0 − 2·(2) = −4 %. ✔<br><br><b>Merk hva b̄m̄ betyr:<\/b> produktet er AD-kurvens helning. Større b̄ (mer rentefølsom økonomi) eller større m̄ (mer aggressiv sentralbank) gir <b>flatere<\/b> AD — sterkere realøkonomisk utslag av inflasjonsavvik.","id":69},{"n":3,"k":"Åpen økonomi / Norge","s":"Oljeprisen stiger kraftig. Hva er effekten på Fastlands-Norge? (Pass på nyansen.)","f":"Oljepris er et sjokk med <b>flere kanaler<\/b>:<br><br><b>1. Tilbudssidekanal (som for alle land):<\/b> høyere energikostnader ⇒ <b>ō ↑<\/b> ⇒ AS skifter opp ⇒ inflasjonspress og lavere produksjon.<br><br><b>2. Etterspørselskanal (spesielt for Norge):<\/b> Norge er netto oljeeksportør ⇒ høyere eksportinntekter og økte petroleumsinvesteringer ⇒ <b>ā_nx ↑<\/b> ⇒ AD skifter ut. Isolert sett positivt.<br><br><b>3. Den viktige nyansen for FASTLANDS-Norge:<\/b> her kan <b>negative<\/b> effekter dominere. Høyere energipriser reduserer husholdningenes kjøpekraft (ā_c ↓) og øker bedriftenes kostnader (ā_i ↓). Samtidig kan en sterkere krone (økte oljeinntekter) svekke konkurranseevnen til øvrig eksportindustri.<br><br><b>Konklusjon:<\/b> for totaløkonomien er effekten positiv, men for <b>Fastlands-Norge kan netto ā-effekt være negativ<\/b> fordi fallet i ā_c og ā_i dominerer. Vis at du kjenner dette skillet.","id":70},{"n":3,"k":"Myndigheter / forventninger","s":"Forklar inflasjonen på 1970-tallet med modellen — tre faktorer.","f":"<b>1. Oljeprissjokk (1974 og 1979):<\/b> Kostnadssjokk ⇒ <b>ō > 0<\/b> ⇒ AS/Phillips skifter opp ⇒ stagflasjon (høy inflasjon + lav produksjon samtidig).<br><br><b>2. For ekspansiv pengepolitikk på feil teorifundament:<\/b> En utbredt tro på en <b>permanent<\/b> avveining mellom inflasjon og ledighet — at man kunne «kjøpe» varig lavere ledighet med varig høyere inflasjon ved å bevege seg langs Phillips-kurven. Dette er feil: under adaptive forventninger skifter kurven opp, og man ender med høyere inflasjon uten lavere ledighet.<br><br><b>3. Imperfekt informasjon:<\/b> Sentralbanken <b>undervurderte fallet i produktivitetsveksten<\/b> — den tolket lavere BNP-vekst som en konjunkturell nedgang (negativt gap) i stedet for lavere <b>potensial<\/b>. Derfor satte den renten ned og presset inflasjonen ytterligere opp.<br><br><b>Lærdom:<\/b> dette formet moderne inflasjonsstyring — eksplisitte mål, uavhengighet og fokus på å forankre forventninger.","id":71},{"n":3,"k":"Myndigheter / forventninger","s":"Volcker-disinflasjonen: hvorfor var den så kostbar?","f":"<b>Hypotetisk:<\/b> Hvis den klassiske dikotomien hadde holdt <i>på kort sikt<\/i>, kunne inflasjonen vært redusert <b>kostnadsfritt<\/b> — bare senk pengemengdeveksten, så faller inflasjonen tilsvarende (kvantitetsteorien).<br><br><b>Men dikotomien holder ikke på kort sikt<\/b>, fordi inflasjonen er treg og forventningene adaptive.<br><br><b>Hva som faktisk skjedde:<\/b><br>1. Volcker strammet kraftig til (høy nominell rente)<br>2. Siden π var treg, steg <b>realrenten<\/b> R = i − π kraftig<br>3. Via IS ga dette et stort <b>negativt produksjonsgap<\/b> — en dyp resesjon<br>4. Via Phillips (Δπ = v̄·Ỹ < 0) presset det negative gapet inflasjonen gradvis ned<br><br><b>Poenget:<\/b> under adaptive forventninger er resesjonen <i>mekanismen<\/i> som får inflasjonen ned. Kostnaden kalles <b>offerraten<\/b> (sacrifice ratio).<br><br><b>Kontrast:<\/b> med troverdig mål og rasjonelle forventninger kunne mye av dette vært unngått.","id":72},{"n":3,"k":"Nasjonalregnskap","s":"Regn BNP på tre måter: bedrift A selger korn for 100 (ingen vareinnsats), B kjøper kornet og selger mel for 180, C kjøper melet og selger brød for 300. Lønn utgjør 60 % av verdiskapingen i hvert ledd.","f":"<b>Produksjonssiden (sum verdiskaping):<\/b><br>• A: 100 − 0 = 100<br>• B: 180 − 100 = 80<br>• C: 300 − 180 = 120<br>• <b>Sum = 300<\/b><br><br><b>Utgiftssiden:<\/b> Sluttleveringen er brødet til konsumentene = <b>300<\/b> ✔<br><br><b>Inntektssiden:<\/b><br>• Lønn: 0,6 · 300 = 180<br>• Overskudd/kapitalavkastning: 0,4 · 300 = 120<br>• <b>Sum = 300<\/b> ✔<br><br><b>Alle tre gir 300.<\/b><br><br><b>Kommentar til sensor:<\/b> arbeidsinntektsandelen på 60 % er nær den empiriske verdien på ca. 2/3, som svarer til 1−α i Cobb-Douglas. Merk også at man <b>ikke<\/b> summerer omsetningen (100+180+300 = 580) — det ville dobbelttelle vareinnsatsen.","id":73},{"n":3,"k":"AS-AD","s":"En kredittskvis øker risikopremien f̄ kraftig, men styringsrenten er allerede nær null. Analyser.","f":"<b>1. Sjokket:<\/b> f̄ ↑ betyr at renten privat sektor betaler (R = R_ff + f̄) stiger, <b>selv om sentralbanken ikke har gjort noe<\/b>.<br><br><b>2. Effekt på AD:<\/b> Fra Ỹₜ = ā − b̄f̄ − b̄m̄(πₜ − π̄) skifter <b>AD innover<\/b> med b̄·Δf̄. Vi får negativt produksjonsgap og fallende inflasjon.<br><br><b>3. Normal respons:<\/b> Sentralbanken ville kuttet R_ff for å motvirke — men den er ved <b>nullgrensen (ZLB)<\/b> og kan ikke kutte mer.<br><br><b>4. Forverrende spiral:<\/b> Med negativt gap faller inflasjonen (Δπ = v̄Ỹ < 0). Blir π negativ (deflasjon), <b>stiger realrenten<\/b> R = i − π selv med i = 0 ⇒ AD presses ytterligere inn ⇒ dypere nedgang. Dette er den farlige deflasjonsspiralen.<br><br><b>5. Politikkverktøy som gjenstår:<\/b><br>• <b>QE<\/b> — kjøp av verdipapirer for å presse ned lange renter og selve risikopremien f̄<br>• <b>Finanspolitikk<\/b> — ekspansiv bruk skifter AD ut igjen (ā ↑). Særlig virkningsfull ved ZLB, siden pengepolitikken ikke kan motvirke den<br>• <b>Kommunikasjon<\/b> om at renten holdes lav lenge (forventningsstyring)<br>• <b>Finansielle tiltak<\/b> — likviditetsstøtte og garantier som direkte reduserer f̄","id":74},{"n":3,"k":"Åpen økonomi / Norge","s":"Norges Bank vurderer å kutte renten mens inflasjonen fortsatt er over målet. Drøft avveiningen.","f":"<b>Argumenter FOR å vente (holde renten høy):<\/b><br>• Etter Taylor-regelen tilsier πₜ > π̄ en realrente over r̄<br>• Kutter man for tidlig, risikerer man at <b>inflasjonsforventningene fester seg<\/b> over målet. Under adaptive forventninger blir det da langt dyrere å få inflasjonen ned senere (Volcker-lærdommen)<br>• <b>Troverdighet<\/b> er selve fundamentet i inflasjonsstyring — den er dyr å bygge og lett å miste<br>• Et kutt svekker kronen (UIP), som gir <b>importert inflasjon<\/b> — motsatt av det man ønsker<br><br><b>Argumenter FOR å kutte:<\/b><br>• Pengepolitikk virker med <b>etterslep<\/b>, og mandatet er <b>fremoverskuende<\/b> — hvis prognosen viser inflasjonen på vei mot 2 %, kan kutt være riktig <i>før<\/i> man er der<br>• Mandatet er <b>fleksibelt<\/b>: hensynet til «høy og stabil produksjon og sysselsetting» teller også. Et stort negativt produksjonsgap eller stigende ledighet (Okun) taler for lettelser<br>• Er den gjenstående inflasjonen drevet av et <b>midlertidig kostnadssjokk<\/b> (ō) som er i ferd med å gå ut, kan man «se gjennom» det — å stramme mot et tilbudssjokk forverrer produksjonsfallet unødig<br>• Høy gjeld i norske husholdninger gjør gjennomslaget sterkt (stor b̄) — man risikerer å stramme for mye<br><br><b>Konklusjon:<\/b> Avveiningen avhenger av <b>hvorfor<\/b> inflasjonen er høy. Er den <b>etterspørselsdrevet<\/b> (positivt Ỹ), tilsier det fortsatt stram politikk. Er den drevet av et avtakende <b>tilbudssjokk<\/b> og forventningene er godt forankret, forsvarer det gradvis nedtrapping. Nøkkelen er om <b>forventningene er forankret<\/b> — er de det, har banken råd til fleksibilitet.","id":75},{"n":3,"k":"Phillips / AS","s":"Et negativt prissjokk (ō < 0) treffer — f.eks. billig import fra Kina. Analyser.","f":"<b>Speilbildet av stagflasjon:<\/b><br><br><b>1.<\/b> ō < 0 skifter <b>AS ned/høyre<\/b> — bedriftene får lavere kostnader og setter lavere priser ved gitt produksjon.<br><br><b>2.<\/b> Inflasjonen faller under målet. Sentralbanken responderer (MP) med <b>lavere realrente<\/b> ⇒ bevegelse <b>langs AD<\/b> ⇒ <b>høyere produksjon<\/b>.<br><br><b>3. Resultat:<\/b> <b>Lavere inflasjon OG høyere produksjon<\/b> samtidig — det beste av begge verdener. Via Okun faller også ledigheten.<br><br><b>Historisk eksempel:<\/b> «Kina-sjokket» på 1990- og 2000-tallet, der billige importvarer holdt inflasjonen nede i vestlige land samtidig som veksten var god. Dette bidro til «the Great Moderation».<br><br><b>Dynamikk:<\/b> Når sjokket går ut (ō tilbake til 0), skifter AS gradvis opp igjen ettersom πₜ₋₁ har falt. Økonomien vender tilbake til A.<br><br><b>Politikkpoeng:<\/b> Et positivt tilbudssjokk gir sentralbanken en <b>gratis lunsj<\/b> — den kan stimulere uten inflasjonskostnad. Dette er motsatt av avveiningen ved stagflasjon, der begge mål trekker i hver sin retning.","id":76},{"n":3,"k":"IS-kurven","s":"Regn: ā = 0,02, b̄ = 3, r̄ = 2 %, og sentralbanken setter R = 5 %. Finn produksjonsgapet og tolk.","f":"<b>IS: Ỹ = ā − b̄(R − r̄)<\/b><br><br>Ỹ = 0,02 − 3·(0,05 − 0,02) = 0,02 − 3·0,03 = 0,02 − 0,09 = <b>−0,07 = −7 %<\/b><br><br><b>Tolkning:<\/b> Faktisk BNP ligger 7 % under potensielt BNP — en <b>kraftig lavkonjunktur<\/b>. Selv om det er et positivt etterspørselssjokk (ā = 2 %), dominerer den svært stramme pengepolitikken (R hele 3 prosentpoeng over r̄, med høy rentefølsomhet b̄ = 3).<br><br><b>Via Okun:<\/b> u − ū = −0,5·(−7) = <b>+3,5 prosentpoeng<\/b> ledighet over naturlig nivå.<br><br><b>Via Phillips:<\/b> Δπ = v̄·(−7) + 0 < 0 — inflasjonen faller markert.<br><br><b>Politikkvurdering:<\/b> En så stram innretning er bare forsvarlig hvis inflasjonen er svært høy. Ellers bør renten kuttes kraftig — mandatets hensyn til «høy og stabil produksjon og sysselsetting» ville tilsi at et gap på −7 % er uakseptabelt over tid.","id":77},{"n":3,"k":"Myndigheter / forventninger","s":"Hvorfor kan det være farlig å stramme kraftig inn mot et TILBUDSSJOKK? Drøft avveiningen.","f":"<b>Problemet:<\/b> Ved et positivt prissjokk (ō > 0) skifter AS opp, og vi får <b>stagflasjon<\/b> — inflasjonen stiger <i>samtidig<\/i> som produksjonen faller.<br><br>Sentralbankens to mål trekker nå i <b>motsatt retning<\/b>:<br>• Inflasjonsmålet tilsier <b>innstramming<\/b><br>• Hensynet til produksjon/sysselsetting tilsier <b>lettelse<\/b><br><br><b>Faren ved kraftig innstramming:<\/b> Renteøkning gir en bevegelse langs AD til enda <b>lavere produksjon<\/b>. Man forsterker altså realøkonomisk det sjokket allerede har påført. Ved store sjokk kan dette gi unødig dyp resesjon og høy ledighet (Okun).<br><br><b>Faren ved å ikke gjøre noe:<\/b> Hvis sjokket varer, eller hvis <b>forventningene fester seg<\/b> på et høyt nivå (adaptive forventninger!), blir inflasjonen selvforsterkende. Da må man senere stramme <i>enda<\/i> hardere — Volcker-scenariet.<br><br><b>Løsningen i praksis — fleksibel inflasjonsstyring:<\/b> Mandatets «<b>over tid<\/b>» lar Norges Bank bringe inflasjonen tilbake til målet <b>gradvis<\/b>, og dermed fordele belastningen mellom inflasjon og produksjon. Man kan «se gjennom» et <i>midlertidig<\/i> sjokk — <b>forutsatt<\/b> at forventningene forblir forankret.<br><br><b>Nøkkelvurdering:<\/b> Er sjokket midlertidig og forventningene forankret ⇒ vær tålmodig. Er det vedvarende eller forventningene i bevegelse ⇒ stram inn, selv om det koster.","id":78},{"n":3,"k":"Nasjonalregnskap","s":"Beregn produksjonsgapet: faktisk BNP er 4 750 mrd, potensielt BNP er 5 000 mrd. Tolk, og finn ledighet og inflasjonseffekt.","f":"<b>Produksjonsgap:<\/b><br>Ỹ = (Y − Ȳ)/Ȳ = (4 750 − 5 000)/5 000 = −250/5 000 = <b>−0,05 = −5 %<\/b><br><br><b>Tolkning:<\/b> Økonomien produserer 5 % mindre enn den bærekraftig kunne — en betydelig lavkonjunktur med ledig kapasitet i både arbeidsmarkedet og kapitalutstyret.<br><br><b>Via Okuns lov:<\/b> u − ū = −0,5·(−5) = <b>+2,5 prosentpoeng<\/b>. Er ū = 4 %, er faktisk ledighet ca. 6,5 %.<br><br><b>Via Phillips-kurven:<\/b> Δπ = v̄·(−5) + ō. Med v̄ = 0,5 og ō = 0: Δπ = <b>−2,5 prosentpoeng<\/b> — inflasjonen faller markert.<br><br><b>Politikkanbefaling:<\/b> Med negativt gap og fallende inflasjon tilsier både Taylor-regelen (π under mål) og produksjonshensynet <b>ekspansiv<\/b> pengepolitikk: realrenten bør settes <b>under<\/b> r̄. Via IS stimulerer det investeringer og konsum, og via valutakanalen svekkes kronen slik at nettoeksporten øker.","id":79},{"n":3,"k":"Lang sikt (vekst/inflasjon)","s":"Et land har gM = 12 % og gY = 3 %. Finn langsiktig inflasjon, og drøft hva som kan ligge bak.","f":"<b>Kvantitetsteorien:<\/b> π* = gM − gY = 12 % − 3 % = <b>9 %<\/b><br><br><b>Hva ligger bak en så høy pengevekst?<\/b> Se på statens budsjettbetingelse:<br><b>G = T + ΔB + ΔM<\/b><br><br>Vedvarende høy ΔM tyder på at staten <b>finansierer utgifter med seddelpressen<\/b> — typisk fordi:<br>• skattegrunnlaget er svakt eller skatteøkninger er politisk umulige (lav T)<br>• ingen vil låne staten penger til akseptabel rente (begrenset ΔB)<br><br><b>Hvem betaler?<\/b> <b>Seignorage<\/b> — inflasjonsskatten — betales av dem som <b>holder penger<\/b>, siden deres beholdning taper realverdi.<br><br><b>Sargents poeng:<\/b> «Persistent high inflation is always and everywhere a <b>fiscal<\/b> phenomenon.» Friedman har rett i at inflasjon er et monetært fenomen (mekanismen), men den underliggende <i>årsaken<\/i> til vedvarende høy pengevekst er finanspolitisk.<br><br><b>Løsning:<\/b> Uavhengig sentralbank med lovfestet prisstabilitetsmål, som fjerner politikernes mulighet til å beordre seddelpressen — kombinert med finanspolitisk konsolidering.","id":80},{"n":3,"k":"AS-AD","s":"Sammenlign responsen på et negativt etterspørselssjokk i en LUKKET vs. en ÅPEN økonomi.","f":"<b>Lukket økonomi:<\/b><br>1. ā ↓ ⇒ IS/AD skifter inn ⇒ negativt produksjonsgap, fallende inflasjon<br>2. Sentralbanken kutter renten (MP ned) ⇒ bevegelse langs IS ⇒ investering og konsum stimuleres<br>3. <b>Én kanal:<\/b> renten → investering/konsum<br><br><b>Åpen økonomi (Norge):<\/b><br>1. Samme utgangspunkt: ā ↓ ⇒ AD skifter inn<br>2. Sentralbanken kutter renten<br>3. <b>To kanaler:<\/b><br>&nbsp;&nbsp;• <i>IS-kanalen:<\/i> lavere R ⇒ mer investering og konsum<br>&nbsp;&nbsp;• <i>Valutakanalen:<\/i> lavere norsk rente ⇒ kapital ut (UIP) ⇒ <b>kronen svekkes<\/b> (ε ↑) ⇒ norske varer billigere ute ⇒ <b>nettoeksporten stiger<\/b><br><br><b>Konklusjon:<\/b> Pengepolitikken virker <b>kraftigere<\/b> i den åpne økonomien fordi begge kanaler trekker samme vei. Samtidig får den åpne økonomien en <b>ekstra automatisk stabilisator<\/b>: kursen svekkes ofte av seg selv i uro (flight-to-safety), som demper sjokket <i>før<\/i> renten er endret.<br><br><b>Men — kostnaden:<\/b> Den åpne økonomien er også <b>mer utsatt<\/b> for sjokk utenfra (utenlandske renter, eksportetterspørsel, handelspolitikk), som alle skifter norsk AD. Det er en del av begrunnelsen for at Norge trenger <b>egen<\/b> pengepolitikk (trilemmaet).","id":81},{"n":4,"k":"AS-AD","s":"Utled AD-kurven fra IS og MP, og vis deretter at likevekten er Ỹ* = 0, π* = π̄.","f":"<b>Utledning av AD:<\/b><br>IS: Ỹₜ = ā − b̄(Rₜ − r̄)<br>MP: Rₜ = m̄(πₜ − π̄) + r̄ ⇒ <b>Rₜ − r̄ = m̄(πₜ − π̄)<\/b><br><br>Sett MP inn i IS:<br>Ỹₜ = ā − b̄·[m̄(πₜ − π̄)]<br><b>AD: Ỹₜ = ā − b̄m̄(πₜ − π̄)<\/b> ∎<br><br><b>Utledning av likevekt:<\/b><br>Likevekt krever konstant inflasjon (πₜ = πₜ₋₁) og ingen sjokk (ā = 0, ō = 0).<br><br>Fra AS: πₜ = πₜ₋₁ + v̄·Ỹₜ + ō. Med πₜ = πₜ₋₁ og ō = 0:<br>0 = v̄·Ỹₜ ⇒ <b>Ỹ* = 0<\/b> (siden v̄ > 0)<br><br>Sett dette inn i AD, med ā = 0:<br>0 = 0 − b̄m̄(π* − π̄) ⇒ <b>π* = π̄<\/b> (siden b̄m̄ > 0)<br><br>Og fra MP: R* = m̄(π̄ − π̄) + r̄ = <b>r̄<\/b> ∎<br><br><b>Tolkning:<\/b> faktisk BNP = potensielt BNP, inflasjonen er på målet, og realrenten er på sitt naturlige nivå.","id":82},{"n":4,"k":"Lang sikt (vekst/inflasjon)","s":"Utled den naturlige ledighetsraten fra badekarmodellen. Vis alle steg.","f":"<b>Ligninger:<\/b><br>(1) Eₜ + Uₜ = L (konstant arbeidsstyrke)<br>(2) ΔUₜ₊₁ = s·Eₜ − f·Uₜ<br><br><b>Steg 1 — steady state:<\/b> Vannstanden er konstant, sett ΔUₜ₊₁ = 0:<br>0 = s·Eₜ − f·Uₜ<br><br><b>Steg 2 — substituer inn E = L − U<\/b> fra (1):<br>0 = s·(L − Uₜ) − f·Uₜ<br>0 = sL − sUₜ − fUₜ<br><br><b>Steg 3 — løs for U:<\/b><br>sL = (f + s)·U*<br>U* = sL/(f + s)<br><br><b>Steg 4 — del på L for å få raten:<\/b><br><b>u* = U*/L = s/(f + s)<\/b> ∎<br><br><b>Tolkning:<\/b> Den naturlige ledighetsraten avhenger <i>kun<\/i> av separasjons- og jobbfinneraten — arbeidsstyrkens størrelse faller ut. Eneste måte å endre u* på er å endre s eller f.","id":83},{"n":4,"k":"AS-AD","s":"Full eksamensbesvarelse: Et kraftig energiprissjokk treffer Norge mens inflasjonen allerede er over målet. Gi et komplett svar med femstegsmalen.","f":"<b>Steg 1 — ligninger:<\/b><br>AD: Ỹₜ = ā − b̄m̄(πₜ − π̄), AS: πₜ = πₜ₋₁ + v̄·Ỹₜ + ō. Sjokket er <b>ō > 0<\/b>.<br><br><b>Steg 2 — mekanisme:<\/b> Høyere energipriser øker bedriftenes kostnader direkte. De velter kostnadene over i prisene, uavhengig av etterspørselen ⇒ AS skifter opp. Sentralbanken responderer via MP-regelen med høyere realrente, som via IS demper investeringer og konsum.<br><br><b>Steg 3 — figur:<\/b> Tegn AS-AD med akser (πₜ vertikalt, Ỹₜ horisontalt). Marker likevekt A, AS skiftet opp til AS′, og nytt punkt B oppe til venstre på AD.<br><br><b>Steg 4 — analyse:<\/b><br>• <i>Periode 1:<\/i> Bevegelse langs AD til B — <b>høyere inflasjon OG lavere produksjon = stagflasjon<\/b>. Via Okun stiger ledigheten.<br>• <i>Videre:<\/i> Med ō tilbake til 0 skifter AS gradvis ned ettersom πₜ₋₁ faller. Bevegelse langs AD tilbake mot A. Tar flere perioder pga. adaptive forventninger.<br>• <i>Fare:<\/i> Siden inflasjonen allerede var over målet, er risikoen at forventningene <b>fester seg<\/b> på et høyt nivå — da blir returen langt dyrere.<br><br><b>Steg 5 — POLITIKKANBEFALING (avgjørende):<\/b><br>«Inflasjonen ligger klart over målet (πₜ > π̄). Etter Taylor-regelen Rₜ = m̄(πₜ − π̄) + r̄ bør Norges Bank <b>holde realrenten over r̄<\/b>, altså en innstrammende innretning. Via IS demper den høyere realrenten investeringer og konsum, og via valutakanalen styrkes kronen slik at nettoeksporten faller — begge lukker det inflasjonsdrivende presset. <b>Renten bør ikke kuttes før inflasjonsforventningene er tydelig forankret<\/b>, siden et for tidlig kutt risikerer å låse inflasjonen på et høyt nivå. Finanspolitikken bør holdes om lag nøytral for ikke å motvirke pengepolitikken; handlingsregelen gir samtidig rom for målrettede tiltak mot de hardest rammede husholdningene.»<br><br><b>Merk:<\/b> et sjokk som treffer både AS og realøkonomien gir sentralbanken en reell avveining mellom å stabilisere inflasjon og produksjon — det er nettopp derfor mandatet er <i>fleksibelt<\/i>.","id":84},{"n":4,"k":"Åpen økonomi / Norge","s":"Forklar trilemmaet, hvilke to Norge velger, og hvorfor det er velbegrunnet.","f":"<b>Trilemmaet (den umulige treenighet):<\/b> Et land kan ha høyst <b>to<\/b> av tre: (1) selvstendig pengepolitikk, (2) fri kapitalflyt, (3) fast valutakurs.<br><br><b>Norges valg:<\/b> selvstendig pengepolitikk + fri kapitalflyt ⇒ må gi slipp på fast kurs ⇒ <b>flytende valutakurs<\/b>.<br><br><b>Alternativene og deres kostnader:<\/b><br>• <b>Fast kurs<\/b> (f.eks. euro): fjerner valutakursusikkerhet, men Norge må gi opp egen pengepolitikk. ESB-renten settes for eurosonen og kan passe dårlig når Norge treffes av <i>andre<\/i> sjokk.<br>• <b>Lukkede kapitalmarkeder<\/b> (Kina-modellen): kan ha både stabil kurs og egen rente, men er lite attraktivt for en avansert, åpen økonomi.<br><br><b>Hvorfor Norges valg er velbegrunnet:<\/b> Norge er sterkt eksponert mot <b>olje-, gass- og energipriser<\/b> — sjokk som i stor grad er <i>særnorske<\/i> og ikke deles med handelspartnerne. Evnen til å sette en rente tilpasset norske forhold er derfor svært verdifull. I tillegg fungerer den flytende kursen som en <b>automatisk støtdemper<\/b>: ved et negativt sjokk svekkes kronen, som stimulerer eksporten og demper nedgangen.","id":85},{"n":4,"k":"Åpen økonomi / Norge","s":"Er det norske makroøkonomiske rammeverket godt rustet mot internasjonale sjokk? Gi et fullstendig svar.","f":"<b>Ja — rammeverket er robust, av fire grunner:<\/b><br><br><b>1. Norges Bank og fleksibel inflasjonsstyring.<\/b> Styringsrenten settes for å stabilisere inflasjonen, men mandatet («over tid» nær 2 %) gir rom for å vektlegge <b>høy og stabil produksjon og sysselsetting<\/b> og å motvirke finansielle ubalanser. Ved et sjokk kan banken derfor balansere hensynene i stedet for å reagere mekanisk.<br><br><b>2. Handlingsregelen og oljefondet (SPU).<\/b> Finanspolitikken finansieres delvis av forventet realavkastning fra fondet. Fondets størrelse gir Norge betydelig <b>handlingsrom til å bruke mer i nedgangstider<\/b> — som under koronapandemien — uten å undergrave bærekraften. I tillegg virker <b>automatiske stabilisatorer<\/b> uten vedtak.<br><br><b>3. Flytende kurs og «flight-to-safety».<\/b> I urolige tider svekkes små valutaer som NOK. Det <b>stimulerer norsk eksport<\/b>, og fondet — investert i dollar og euro — blir verdt <b>flere kroner<\/b>, slik at impulsene inn i norsk økonomi øker. En innebygd stabilisator som virker akkurat når man trenger den.<br><br><b>4. Samarbeid og åpenhet.<\/b> Tett samarbeid med handelspartnere demper utslagene av handelskonflikter.<br><br><b>Balansert konklusjon:<\/b> Rammeverket er robust og gir uvanlig godt handlingsrom sammenlignet med de fleste land. <b>Men<\/b> Norge er en liten, svært åpen økonomi — vi kan ikke vente store <i>positive<\/i> impulser fra global uro, bare at virkemidlene demper utslagene. Ved svært store eller vedvarende sjokk vil også Norge merke betydelige realøkonomiske konsekvenser.","id":86},{"n":4,"k":"Myndigheter / forventninger","s":"Hvorfor avhenger effekten av en renteendring på samlet konsum av HVEM som rammes? (V24 Oppgave 3.4)","f":"Fordi <b>substitusjonseffekten og inntektseffekten virker ulikt for ulike husholdninger<\/b>.<br><br><b>Substitusjonseffekten — lik for alle:<\/b> Høyere rente gjør konsum i dag dyrere relativt til konsum i morgen. Alle vrir seg mot mindre konsum nå og mer sparing (eller raskere nedbetaling av gjeld). Entydig negativ på dagens konsum.<br><br><b>Inntektseffekten — ASYMMETRISK:<\/b><br>• For <b>sparere<\/b> (netto finansformue): høyere rente gir <b>høyere<\/b> renteinntekter ⇒ positiv inntektseffekt ⇒ kan konsumere mer<br>• For <b>låntakere<\/b> (netto gjeld): høyere rente gir <b>høyere<\/b> rentekostnader ⇒ negativ inntektseffekt ⇒ må konsumere mindre<br><br><b>Aggregert konsekvens:<\/b> For låntakere trekker <i>begge<\/i> effektene i samme retning ⇒ kraftig konsumfall. For sparere trekker de mot hverandre ⇒ liten netto effekt.<br><br><b>MPC-heterogenitet forsterker dette:<\/b> Særlig <b>unge og lavinntektshusholdninger<\/b> har høy gjeld <i>og<\/i> høy marginal konsumtilbøyelighet (MPC) — de kutter mye. <b>Eldre og rikere<\/b> har lav gjeld og lav MPC — de påvirkes lite. (Fagereng, Holm & Natvik 2021 finner nettopp at lav likviditet og små gevinster gir MPC nær 1.)<br><br><b>Konklusjon:<\/b> Pengepolitikkens gjennomslag avhenger av <b>gjelds- og MPC-fordelingen<\/b> i økonomien — og politikken har derfor betydelige <b>fordelingskonsekvenser<\/b>. I Norge, med høy husholdningsgjeld og mange med flytende rente, er gjennomslaget spesielt sterkt.","id":87},{"n":4,"k":"Myndigheter / forventninger","s":"Vis formelt at disinflasjon kan bli kostnadsfri under rasjonelle forventninger og troverdighet.","f":"<b>Utgangspunkt — generell AS:<\/b><br>πₜ = πₜᵉ + v̄·Ỹₜ + ō<br><br><b>Antakelse:<\/b> forventningene er rasjonelle <i>og<\/i> sentralbanken er troverdig, slik at aktørene setter πₜᵉ = <b>π̄′<\/b> (det nye målet) umiddelbart når det annonseres.<br><br><b>Ny AS:<\/b> πₜ = π̄′ + v̄·Ỹₜ + ō<br><b>Ny AD:<\/b> Ỹₜ = ā − b̄m̄(πₜ − π̄′)<br><br><b>Ta endringer<\/b> (fra gammel til ny likevekt):<br>Δπ = Δπ̄ + v̄·ΔỸ + Δō<br><br>Med ingen nye sjokk (Δō = 0) og hvis produksjonsgapet holdes uendret (ΔỸ = 0):<br><b>Δπ = Δπ̄<\/b> ∎<br><br><b>Tolkning:<\/b> Inflasjonen faller med <b>nøyaktig<\/b> målendringen, <b>uten<\/b> noe produksjonsfall. Disinflasjonen er kostnadsfri.<br><br><b>Sjekk konsistens:<\/b> Med Ỹ = 0 og π = π̄′ gir AD: 0 = 0 − b̄m̄(π̄′ − π̄′) = 0 ✔<br><br><b>Forutsetningene er alt:<\/b> Dette krever <b>åpenhet<\/b> om målet og <b>tillit<\/b> til at sentralbanken faktisk gjennomfører. Uten troverdighet faller vi tilbake til adaptive forventninger og Volcker-scenariet med en dyp resesjon. Dette er den viktigste begrunnelsen for sentralbankuavhengighet og eksplisitte inflasjonsmål.","id":88},{"n":4,"k":"Pengepolitikk / MP","s":"Hvorfor følger ikke Norges Bank en mekanisk Taylor-regel? Forklar «constrained discretion».","f":"<b>Den enkle MP-regelen<\/b> Rₜ = m̄(πₜ − π̄) + r̄ reagerer bare på inflasjonsavviket. Norges Banks faktiske mandat er bredere.<br><br><b>Hvorfor ikke mekanisk:<\/b><br>1. <b>Mandatet er fleksibelt:<\/b> målet er inflasjon «over tid» nær 2 %, og styringen skal <i>også<\/i> bidra til høy og stabil produksjon og sysselsetting og motvirke finansielle ubalanser. Ved et prissjokk (stagflasjon) vil en mekanisk regel kreve kraftig innstramming som forverrer produksjonsfallet — fleksibiliteten lar banken fordele belastningen over tid.<br>2. <b>Fremoverskuende:<\/b> pengepolitikk virker med etterslep, så banken må reagere på <i>prognoser<\/i>, ikke bare dagens tall.<br>3. <b>Sjokkene er ulike:<\/b> et etterspørselssjokk krever motsatt respons av et tilbudssjokk — en enkel regel skiller ikke.<br><br><b>Men hvorfor da ha et mål i det hele tatt?<\/b> Fordi ren <b>diskresjon<\/b> gir <b>inflation bias<\/b> (Kydland-Prescott): uten binding forventer aktørene at banken vil overraske, og priser inn høyere inflasjon.<br><br><b>«Constrained discretion» (Bernanke)<\/b> er mellomløsningen: sentralbanken har <b>frihet<\/b> til å reagere på kortsiktige forstyrrelser, men er <b>bundet<\/b> av en troverdig forpliktelse til målet på sikt. Formuleringen <b>«over tid»<\/b> i forskriften er nettopp denne balansen — den gir fleksibilitet uten å slippe forventningsankeret.","id":89},{"n":4,"k":"AS-AD","s":"Post-covid-inflasjonen i Norge: forklar utviklingen grafisk i AS-AD. (H25 Oppgave 3c)","f":"<b>Fase 1 — det opprinnelige sjokket:<\/b> Den kraftige prisveksten startet som et <b>importert kostnadssjokk<\/b> (globale leveransekjedeproblemer, energipriser) ⇒ <b>ō > 0<\/b> ⇒ <b>AS skifter opp<\/b>. Resultat: høy inflasjon, press på realøkonomien.<br><br><b>Fase 2 — innstramming og avkjøling:<\/b> Høy inflasjon utløste kraftige renteøkninger. Via IS ga dette avkjøling: svak vekst i om lag to år, der <b>boliginvesteringer og forbruk falt<\/b>, mens offentlig etterspørsel og petroleumsinvesteringer holdt aktiviteten oppe. Importprisveksten avtok, så AS begynte å <b>skifte gradvis tilbake ned<\/b> ettersom πₜ₋₁ falt.<br><br><b>Fase 3 — dagens situasjon:<\/b> Inflasjonen holdes nå oppe <b>innenlands<\/b> — høy tjenesteprisvekst og <b>årslønnsvekst over frontfagsrammen<\/b>. Samtidig har veksten tatt seg opp igjen (sterkere husholdningsetterspørsel) ⇒ <b>AD har skiftet litt til høyre<\/b>.<br><br><b>Samlet grafisk bilde:<\/b> AS først kraftig opp, deretter gradvis ned (men <i>ikke<\/i> helt tilbake), kombinert med et moderat AD-skift til høyre.<br><br><b>Resultat:<\/b> inflasjonen fortsatt <b>over<\/b> 2 %, produksjonsgapet <b>svakt positivt<\/b>.<br><br><b>Politikkimplikasjon:<\/b> Med π > π̄ og Ỹ ≥ 0 tilsier Taylor-regelen fortsatt en realrente over r̄. Styringsrenten ble holdt høy (rundt 4,5 %) i lang tid, med forsiktig nedtrapping ettersom inflasjonen nærmer seg målet. Finanspolitikken bør holdes om lag nøytral.","id":90},{"n":4,"k":"Kort sikt – grunnlag","s":"Hvordan avgjør du om et gitt sjokk er et AD-sjokk eller et AS-sjokk? Gi en systematisk metode.","f":"<b>Nøkkelspørsmål: virker sjokket på ETTERSPØRSELEN etter varer, eller på KOSTNADENE ved å produsere dem?<\/b><br><br><b>AD-sjokk (påvirker ā):<\/b> Alt som endrer C, I, G eller NX ved gitt rente og inflasjon.<br><i>Eksempler:<\/i> endret optimisme/pessimisme, finanspolitisk ekspansjon, boligkrakk (formueseffekt), kredittskvis, svakere eksportmarkeder, endret risikopremie f̄.<br><b>Signatur:<\/b> π og Ỹ beveger seg i <b>SAMME<\/b> retning (begge opp, eller begge ned).<br><br><b>AS-sjokk (påvirker ō):<\/b> Alt som endrer bedriftenes kostnader direkte.<br><i>Eksempler:<\/i> olje-/energipriser, importpriser, toll på innsatsvarer, lønnsvekst utover produktivitet, leveransekjedeproblemer.<br><b>Signatur:<\/b> π og Ỹ beveger seg i <b>MOTSATT<\/b> retning (stagflasjon, eller det motsatte).<br><br><b>Praktisk diagnose fra data:<\/b> Ser du <b>inflasjon opp + produksjon ned<\/b>, må det være et negativt AS-sjokk. Ser du <b>inflasjon opp + produksjon opp<\/b>, er det et positivt AD-sjokk.<br><br><b>Viktig komplikasjon:<\/b> Mange virkelige sjokk er <b>begge deler<\/b>. Toll er det klassiske eksempelet (AD ned via ā_nx <i>og<\/i> AS opp via ō) — da blir inflasjonseffekten tvetydig mens produksjonen entydig faller. Nevn alltid begge kanaler når de finnes.","id":91},{"n":4,"k":"Kort sikt – grunnlag","s":"Hvorfor er det avgjørende at den klassiske dikotomien IKKE holder på kort sikt? Knytt sammen hele pensum.","f":"<b>Den klassiske dikotomien (lang sikt, kap. om inflasjon):<\/b> Den reelle og den nominelle siden av økonomien er atskilt. Penger er <b>nøytrale<\/b> — en dobling av pengemengden dobler bare prisene. Produksjon bestemmes utelukkende av reelle faktorer (K, L, A) fra vekstmodellene, der penger ikke engang forekommer.<br><br><b>På kort sikt brytes dette<\/b>, fordi priser og lønninger er <b>trege<\/b> (menykostnader, nominelle kontrakter, imperfekt informasjon, normer).<br><br><b>Hvorfor dette bruddet er selve forutsetningen for Del III:<\/b><br>1. <b>Treg inflasjon ⇒ sentralbanken kan styre REALrenten.<\/b> Setter den iₜ, følger Rₜ = iₜ − πₜ med. Uten treghet ville π justert seg umiddelbart og R vært upåvirket.<br>2. <b>Realrenten påvirker realøkonomien<\/b> via IS (investeringskanalen).<br>3. <b>Altså har pengepolitikk REELLE effekter<\/b> — den kan brukes til <b>stabilisering<\/b>.<br><br><b>Hvis dikotomien hadde holdt på kort sikt:<\/b> Hele IS-MP-PC-modellen ville vært meningsløs. Renteendringer ville bare flyttet prisnivået, aldri produksjonen. Det ville ikke finnes produksjonsgap å stabilisere, ingen Phillips-avveining, og ingen grunn til å ha en sentralbank som gjør annet enn å holde pengeveksten konstant.<br><br><b>Den store sammenhengen:<\/b> Vekstmodellene (Solow/Romer) forklarer <b>Ȳ<\/b> — nivået økonomien svinger rundt. Kortsiktsmodellen forklarer <b>avvikene<\/b> fra Ȳ. Langsiktsinflasjonsteorien forklarer <b>π̄<\/b> og hvorfor målet må være troverdig. De tre delene av pensum er tre lag i samme bygning — og bruddet på dikotomien er det som gjør det tredje laget mulig.","id":92},{"n":4,"k":"Eksamensteknikk","s":"Hva er femstegsmalen, og hvorfor taper studenter mest poeng på steg 5?","f":"<b>Femstegsmalen for enhver modelloppgave:<\/b><br>1. <b>Definer og skriv ligningen<\/b> — med symbolforklaring<br>2. <b>Forklar intuisjonen/mekanismen<\/b> — <i>hvorfor<\/i> virker sammenhengen<br>3. <b>Tegn og merk figur<\/b> — akser, kurver, likevektspunkt, skift, nye punkter<br>4. <b>Gjennomfør analysen steg for steg<\/b> — sjokk → hvilken kurve skifter → umiddelbar effekt → dynamikk over perioder (A→B→…→A)<br>5. <b>Konkluder<\/b> — og i Oppgave 3: en <b>eksplisitt politikkanbefaling<\/b><br><br><b>Hvorfor steg 5 er der flest poeng tapes:<\/b><br>Mange studenter gjør en helt korrekt <b>retningsanalyse<\/b> («inflasjonen stiger, produksjonen faller») og stopper der. Men sensorveiledningene forventer at svaret <b>kulminerer<\/b> i en begrunnet anbefaling som eksplisitt bruker <b>MP-regelen og IS-mekanismen<\/b>.<br><br><b>Malen for en god anbefaling:<\/b><br>«Inflasjonen ligger [over/under] målet (πₜ [>/<] π̄) og produksjonsgapet er [positivt/negativt]. Etter Taylor-regelen Rₜ = m̄(πₜ − π̄) + r̄ bør Norges Bank sette realrenten [over/under] r̄. Via IS vil dette [dempe/stimulere] investeringer og konsum, og via valutakanalen [styrke/svekke] kronen slik at nettoeksporten [faller/stiger] — begge bidrar til å lukke gapet og bringe inflasjonen mot 2 %. Finanspolitikken bør [holdes nøytral / brukes ekspansivt], og handlingsregelen gir rom for [ … ].»<br><br><b>De tre andre klassiske tapspostene:<\/b> (a) oppgi formel uten mekanisme (steg 2), (b) glemme figur når den kreves (steg 3), (c) hverdagsspråk i stedet for presist modellspråk («skift av AD», ikke «etterspørselen gikk ned»).","id":93},{"n":4,"k":"IS-kurven","s":"Utled IS-kurven fra nasjonalregnskapet. Vis alle steg.","f":"<b>Steg 1 — utgangspunkt:<\/b> Yₜ = Cₜ + Iₜ + Gₜ + NXₜ<br><br><b>Steg 2 — spesifiser hver komponent<\/b> som andel av potensielt BNP:<br>• Cₜ = āc·Ȳₜ (konsumglatting ⇒ avhenger av <i>potensielt<\/i>, ikke faktisk, BNP)<br>• Iₜ/Ȳₜ = āi − b̄(Rₜ − r̄) &nbsp;← <b>eneste rentefølsomme ledd<\/b><br>• Gₜ = āg·Ȳₜ<br>• NXₜ = (āex − āim)·Ȳₜ<br><br><b>Steg 3 — sett inn og del på Ȳₜ:<\/b><br>Yₜ/Ȳₜ = āc + [āi − b̄(Rₜ − r̄)] + āg + (āex − āim)<br><br><b>Steg 4 — trekk fra 1<\/b> (definisjonen Ỹₜ = Yₜ/Ȳₜ − 1):<br>Ỹₜ = [āc + āi + āg + (āex − āim) − 1] − b̄(Rₜ − r̄)<br><br><b>Steg 5 — definer ā<\/b> som klammeuttrykket:<br><b>Ỹₜ = ā − b̄(Rₜ − r̄)<\/b> ∎<br><br><b>Merknad om ā:<\/b> I langsiktig likevekt summerer andelene til 1 (nasjonalregnskapsidentiteten), slik at <b>ā = 0<\/b>. Avvik fra 0 på kort sikt <i>er<\/i> definisjonen på et etterspørselssjokk.<br><br><b>Merknad om helningen:<\/b> Alle de Ȳ-proporsjonale leddene ble konstanter; bare investeringenes renteavhengighet overlevde som helning. Det er derfor <b>investeringskanalen<\/b> er hjertet i modellen.","id":94},{"n":4,"k":"Kort sikt – grunnlag","s":"Vis hvordan IS, MP og Phillips henger sammen som et system. Spor et etterspørselssjokk gjennom alle tre.","f":"<b>Systemet — tre ligninger, tre endogene (Ỹₜ, Rₜ, πₜ):<\/b><br>• <b>IS:<\/b> Rₜ → Ỹₜ (rente bestemmer produksjon)<br>• <b>MP:<\/b> πₜ → Rₜ (inflasjon bestemmer rente)<br>• <b>PC:<\/b> Ỹₜ → πₜ (produksjon bestemmer inflasjon)<br><br>Legg merke til at dette er en <b>lukket sirkel<\/b> — derfor er systemet determinert.<br><br><b>Spor et positivt etterspørselssjokk (ā ↑):<\/b><br><b>1.<\/b> IS skifter ut ⇒ ved uendret rente stiger Ỹ over 0 (positivt produksjonsgap)<br><b>2.<\/b> Phillips: Δπ = v̄·Ỹ > 0 ⇒ inflasjonen begynner å stige<br><b>3.<\/b> MP: πₜ > π̄ ⇒ sentralbanken hever realrenten over r̄<br><b>4.<\/b> IS igjen: høyere R demper investering og konsum ⇒ Ỹ trekkes tilbake mot 0<br><b>5.<\/b> Med Ỹ tilbake mot 0 stopper inflasjonsøkningen (Δπ → 0)<br><b>6.<\/b> Når sjokket dør ut (ā → 0) og forventningene har justert seg, er vi tilbake i A: Ỹ = 0, π = π̄, R = r̄<br><br><b>I AS-AD komprimert:<\/b> Steg 1–3 er sammenfattet i AD-kurven (som allerede inneholder sentralbankresponsen), og steg 2 er AS. Derfor er AS-AD bare en to-kurve-versjon av samme system.<br><br><b>Poenget:<\/b> Det er <b>sentralbankens systematiske respons<\/b> som gjør økonomien selvstabiliserende. Uten den (m̄ ≤ 0) ville sjokket forsterket seg selv.","id":95},{"n":4,"k":"Åpen økonomi / Norge","s":"Full besvarelse: Handelspartnerne opplever kraftig konjunkturnedgang. Analyser konsekvensene for Norge og gi politikkanbefaling.","f":"<b>Steg 1 — identifiser sjokket:<\/b><br>Svakere vekst ute reduserer etterspørselen etter norsk eksport ⇒ <b>ā_nx ↓<\/b> ⇒ dette er et <b>negativt etterspørselssjokk<\/b> i den norske AD-kurven.<br><br><b>Steg 2 — mekanisme:<\/b><br>Lavere eksportetterspørsel reduserer NX direkte. Via multiplikatoreffekten forsterkes det: lavere produksjon i eksportnæringene ⇒ lavere inntekter og sysselsetting ⇒ lavere konsum ⇒ ytterligere fall.<br><br><b>Steg 3 — figur:<\/b> Tegn AS-AD. AD skifter <b>innover<\/b> til AD′. Bevegelse <b>langs AS<\/b> til nytt punkt B nede til venstre.<br><br><b>Steg 4 — analyse:<\/b><br>• <i>Umiddelbart:<\/i> <b>Negativt produksjonsgap<\/b> (Ỹ < 0) og <b>fallende inflasjon<\/b> (π < π̄) — begge faller, som er signaturen på et AD-sjokk.<br>• <i>Via Okun:<\/i> ledigheten stiger med ca. 0,5·|Ỹ| prosentpoeng.<br>• <i>Dynamikk:<\/i> Med negativt gap gir Phillips Δπ = v̄Ỹ < 0 ⇒ inflasjonen fortsetter å falle. AS skifter gradvis ned ettersom πₜ₋₁ synker.<br>• <i>Dempende motkraft:<\/i> Utenlandske sentralbanker vil trolig kutte sine renter i nedgangen. Det svekker deres valuta / styrker kronen relativt — men samtidig kan global uro gi <b>flight-to-safety<\/b> og en <b>svakere krone<\/b>, som stimulerer norsk eksport og delvis motvirker sjokket.<br><br><b>Steg 5 — POLITIKKANBEFALING:<\/b><br>«Både inflasjonen (πₜ < π̄) og produksjonsgapet (Ỹ < 0) trekker i samme retning. Etter Taylor-regelen Rₜ = m̄(πₜ − π̄) + r̄ bør Norges Bank <b>sette realrenten under r̄<\/b> — altså en ekspansiv innretning. Via IS stimulerer lavere realrente investeringer og konsum. Via valutakanalen svekker et rentekutt kronen (UIP), slik at nettoeksporten øker — en ekstra og her særlig verdifull kanal, siden sjokket kom nettopp gjennom eksporten.<br><br>Samtidig bør <b>finanspolitikken<\/b> være ekspansiv. Handlingsregelen og oljefondets størrelse gir Norge uvanlig stort handlingsrom til å bruke mer i nedgangstider, slik vi så under korona. De automatiske stabilisatorene virker i tillegg uten vedtak.<br><br>Siden dette er et rent <b>etterspørselssjokk<\/b>, står ikke sentralbanken overfor noen målkonflikt — begge hensyn (inflasjon og produksjon) tilsier lettelser. Det er en enklere situasjon enn ved et tilbudssjokk.»","id":96},{"n":4,"k":"Eksamensteknikk","s":"Hva er de vanligste feilene i Oppgave 3, og hvordan unngår du dem konkret?","f":"<b>Feil 1 — skift vs. bevegelse langs.<\/b><br>Den absolutt vanligste. Studenter skifter AS når det skulle vært en bevegelse langs, eller omvendt.<br><i>Motmiddel:<\/i> Spør alltid: står variabelen på en <b>akse<\/b>? Da er det bevegelse langs. Er det en <b>eksogen parameter<\/b> (ā, ō, π̄, f̄)? Da skifter kurven. Skriv det eksplisitt: «Siden ā er en eksogen parameter i AD, <b>skifter<\/b> AD utover.»<br><br><b>Feil 2 — mangler andreperiode-dynamikken.<\/b><br>Man viser bare umiddelbar effekt og stopper.<br><i>Motmiddel:<\/i> Legg alltid til et avsnitt om hva som skjer <b>videre<\/b>: «I neste periode er ō = 0, men fordi forventningene er adaptive er πₜ₋₁ nå forhøyet. AS skifter derfor gradvis ned, og økonomien beveger seg langs AD tilbake mot A over flere perioder.»<br><br><b>Feil 3 — AD forklart som vanlig etterspørselskurve.<\/b><br><i>Motmiddel:<\/i> Si eksplisitt at helningen skyldes <b>sentralbankens respons<\/b>: π ↑ ⇒ R ↑ (MP) ⇒ Ỹ ↓ (IS).<br><br><b>Feil 4 — ingen figur.<\/b><br><i>Motmiddel:<\/i> Tegn <b>alltid<\/b> ved sjokkanalyse, selv om det ikke eksplisitt bes om. Merk akser (πₜ, Ỹₜ), begge kurver, likevekt A, skiftet kurve med apostrof, og nytt punkt B.<br><br><b>Feil 5 — ingen eksplisitt politikkanbefaling.<\/b><br>Man beskriver hva som skjer, men svarer aldri på hva myndighetene <b>bør<\/b> gjøre.<br><i>Motmiddel:<\/i> Avslutt <b>hver<\/b> Oppgave 3-del med en anbefaling forankret i Taylor-regelen og IS-mekanismen, pluss finanspolitikkens rolle og norsk institusjonell kontekst.<br><br><b>Feil 6 — hverdagsspråk.<\/b><br>«Folk fikk mindre penger å rutte med» i stedet for «konsumandelen āc faller, slik at ā synker og AD skifter innover».<br><i>Motmiddel:<\/i> Bruk modellens navn på ting — parameter, kurve, skift, gap, likevekt.","id":97},{"n":4,"k":"Lang sikt (vekst/inflasjon)","s":"Sammenlign Solow og Romer: hva forklarer hver av dem, og hvordan utfyller de hverandre?","f":"<b>Solow — kapitalakkumulasjon:<\/b><br>• <i>Forklarer:<\/i> hvorfor land har ulikt <b>inntektsNIVÅ<\/b>, hvorfor fattige land kan vokse raskt (overgangsdynamikk/betinget konvergens), og effekten av sparerate, depresiering og befolkningsvekst<br>• <i>Nøkkelmekanisme:<\/i> avtakende avkastning på kapital<br>• <i>Begrensning:<\/i> gir <b>ingen langsiktig vekst<\/b> per innbygger. I steady state er veksten null. Den langsiktige veksten må komme utenfra, som eksogen vekst i A<br><br><b>Romer — ideer:<\/b><br>• <i>Forklarer:<\/i> hvorfor det finnes <b>varig vekst<\/b> i det hele tatt (g*_y = γn), og hvorfor vekst krever institusjoner som patenter<br>• <i>Nøkkelmekanisme:<\/i> ideer er <b>ikke-rivaliserende<\/b> ⇒ økende skalautbytte ⇒ ingen avtakende avkastning på kunnskap<br>• <i>Begrensning:<\/i> sier lite om kapitalens rolle og om overgangsdynamikk<br><br><b>Hvordan de utfyller hverandre (den kombinerte modellen):<\/b><br>Romer forklarer <b>trendveksten<\/b> — den langsiktige, stigende banen drevet av idéproduksjon. Solow forklarer <b>bevegelsen rundt og mot<\/b> den banen — hvorfor et land kan ligge under sitt potensial og vokse raskt for å ta igjen.<br><br>I den kombinerte modellen vokser A over tid (Romer), mens økonomien konvergerer mot et steady state <i>relativt til<\/i> den voksende A (Solow). Et land kan derfor både vokse langs trenden <b>og<\/b> konvergere mot den samtidig.<br><br><b>Koblingen til Del III:<\/b> Sammen bestemmer disse to <b>Ȳ<\/b> — potensielt BNP. Kortsiktsmodellen forklarer avvikene fra Ȳ. Slik henger hele pensum sammen: vekstmodellene gir nivået, kortsiktsmodellen gir svingningene rundt det.","id":98},{"n":4,"k":"Myndigheter / forventninger","s":"Drøft: bør en sentralbank følge en fast regel eller ha full frihet (diskresjon)?","f":"<b>Argumenter for REGLER:<\/b><br>• <b>Tidskonsistens (Kydland-Prescott):<\/b> Uten binding har sentralbanken insentiv til å overraske med ekspansiv politikk. Aktørene forutser det og priser inn høyere inflasjon ⇒ <b>inflation bias<\/b> — høyere inflasjon <i>uten<\/i> høyere produksjon.<br>• <b>Forventningsforankring:<\/b> En troverdig regel gjør at aktørene setter πᵉ = π̄. Da blir disinflasjon billig, og sjokk får mindre gjennomslag (prissetterne «gjør noe av jobben»).<br>• <b>Forutsigbarhet<\/b> letter planlegging for husholdninger og bedrifter.<br>• <b>Historisk erfaring:<\/b> 1970-tallets diskresjonære politikk, basert på feil teori og dårlig informasjon, endte i høy og vedvarende inflasjon.<br><br><b>Argumenter for DISKRESJON:<\/b><br>• <b>Sjokk er forskjellige:<\/b> Et etterspørselssjokk krever motsatt respons av et tilbudssjokk. En mekanisk regel skiller ikke mellom dem, og vil stramme inn i en stagflasjon — akkurat når produksjonen allerede faller.<br>• <b>Etterslep:<\/b> Politikken virker med forsinkelse, så man må reagere på prognoser, ikke bare på observerte tall.<br>• <b>Ekstraordinære situasjoner<\/b> (finanskrise, ZLB, pandemi) krever verktøy og vurderinger ingen regel kan spesifisere på forhånd.<br><br><b>Konklusjonen i moderne pengepolitikk — «constrained discretion» (Bernanke):<\/b><br>Man kombinerer begge: et <b>eksplisitt, troverdig mål<\/b> (bindingen som forankrer forventningene) med <b>frihet i hvordan og hvor raskt<\/b> man kommer dit.<br><br>Norges Banks mandat er nettopp dette: inflasjonen skal være «<b>over tid<\/b> nær 2 %», og styringen skal være <b>fremoverskuende og fleksibel<\/b> og også vektlegge produksjon, sysselsetting og finansielle ubalanser.<br><br><b>Institusjonell forutsetning:<\/b> For at bindingen skal være troverdig, må sentralbanken være <b>uavhengig<\/b> — ellers kan politikere overstyre den når det passer, og hele forankringen forsvinner.","id":99}]};

(function (S) {
  const { el, icon, escapeHtml } = S.u;
  const sh = () => S.views.shared;
  const D = () => window.SAM3_DATA.dybde;

  /* ---------- lokal filtertilstand (nullstilles ved navigering, ikke persistert) ---------- */
  let fLevels = new Set([1, 2, 3, 4]);
  let fTopic = "alle";
  let viewMode = null; // null | "again" | "unseen"
  let order = null;      // memoisert id-rekkefølge (original eller stokket)
  let shuffled = false;  // true kun når brukeren har blandet rekkefølgen eksplisitt

  function items() { return D().items || []; }
  function ensureOrder() { if (!order) order = items().map((q) => q.id); return order; }

  function marks() { const st = S.store.get(); if (!st.dybde) st.dybde = { marks: {} }; return st.dybde.marks; }
  function markOf(id) { return marks()[id] || null; }
  function setMark(id, val) {
    const m = marks();
    m[id] = m[id] === val ? null : val;
    S.store.emit();
  }
  function counts() {
    const m = marks(); const all = items();
    let ok = 0, no = 0;
    all.forEach((q) => { const v = m[q.id]; if (v === "ok") ok++; else if (v === "no") no++; });
    return { ok, no, unseen: all.length - ok - no, total: all.length };
  }

  function visible() {
    const m = marks(); const byId = {}; items().forEach((q) => (byId[q.id] = q));
    return ensureOrder().map((id) => byId[id]).filter((q) => {
      if (!q) return false;
      if (!fLevels.has(q.n)) return false;
      if (fTopic !== "alle" && q.k !== fTopic) return false;
      const v = m[q.id];
      if (viewMode === "again" && v !== "no") return false;
      if (viewMode === "unseen" && v != null) return false;
      return true;
    });
  }

  /* ---------- rendering ---------- */
  function render() {
    const wrap = el(".fade-in");
    wrap.appendChild(sh().pageHead("Dybdetrening", "100 spørsmål, økende vanskelighetsgrad",
      "Tungt vektet mot Oppgave 3 (kort sikt, AS-AD, IS-MP, åpen økonomi), med grunnlag fra nasjonalregnskap og vekst. Formuler svaret i hodet før du åpner fasiten."));

    wrap.appendChild(el(".card", { style: { marginBottom: "18px", background: "var(--amber-soft)", border: "1px solid #f2dcb6" } },
      el("p", { style: { margin: 0, fontSize: "14.5px", lineHeight: 1.55 } },
        el("b", "Slik bruker du den: "),
        "Les spørsmålet, si svaret høyt eller skriv det ned, før du åpner fasiten. Gjenkjenning er ikke det samme som å kunne. Marker deretter «Kunne den» eller «Må øve», og bruk filteret «Kun må øve» for en rask ny runde. Nivå 1–2 er oppvarming; nivå 3–4 er der eksamenspoengene ligger.")));

    wrap.appendChild(filterPanel());
    const statsPanel = el(".card", { style: { marginBottom: "18px" } });
    wrap.appendChild(statsPanel);

    const list = el("div");
    wrap.appendChild(list);
    paintList(list, statsPanel);
    return wrap;
  }

  function filterPanel() {
    const panel = el(".card", { style: { marginBottom: "18px" } });
    panel.appendChild(el(".nav-section", { style: { paddingLeft: 0 } }, "Nivå"));
    const lvlRow = el(".row.wrap", { style: { gap: "8px", marginBottom: "16px" } });
    [1, 2, 3, 4].forEach((n) => {
      const on = fLevels.has(n);
      lvlRow.appendChild(el(".chip" + (on ? ".accent" : ""), { style: { cursor: "pointer" }, onclick: () => {
        if (fLevels.has(n)) { if (fLevels.size > 1) fLevels.delete(n); } else fLevels.add(n);
        S.app.refresh();
      } }, "Nivå " + n));
    });
    panel.appendChild(lvlRow);

    panel.appendChild(el(".nav-section", { style: { paddingLeft: 0 } }, "Tema"));
    const topicRow = el(".row.wrap", { style: { gap: "8px", marginBottom: "16px" } });
    topicRow.appendChild(el(".chip" + (fTopic === "alle" ? ".accent" : ""), { style: { cursor: "pointer" }, onclick: () => { fTopic = "alle"; S.app.refresh(); } }, "Alle tema"));
    (D().cats || []).forEach((c) => {
      topicRow.appendChild(el(".chip" + (fTopic === c ? ".accent" : ""), { style: { cursor: "pointer" }, onclick: () => { fTopic = c; S.app.refresh(); } }, c));
    });
    panel.appendChild(topicRow);

    panel.appendChild(el(".nav-section", { style: { paddingLeft: 0 } }, "Visning"));
    const seg = el(".seg", { style: { flexWrap: "wrap" } });
    [[null, "Alle spørsmål"], ["again", "Kun «må øve»"], ["unseen", "Kun ikke vurdert"]].forEach(([v, label]) => {
      seg.appendChild(el("button" + (viewMode === v ? ".on" : ""), { onclick: () => { viewMode = v; S.app.refresh(); } }, label));
    });
    const actions = el(".row.wrap", { style: { gap: "8px", marginTop: "10px" } },
      el("button.btn.sm", { onclick: () => { order = shuffleArr(items().map((q) => q.id)); shuffled = true; S.app.refresh(); } }, "Bland rekkefølge"),
      el("button.btn.sm", { onclick: () => { document.querySelectorAll("details.dyb-q[open]").forEach((d) => d.removeAttribute("open")); } }, "Lukk alle svar"),
      el("button.btn.sm.ghost", { onclick: () => {
        if (confirm("Nullstille alle vurderinger («kunne»/«må øve») i Dybdetrening? Kan ikke angres.")) {
          const st = S.store.get(); st.dybde = { marks: {} }; S.store.emit();
          fLevels = new Set([1, 2, 3, 4]); fTopic = "alle"; viewMode = null; order = null; shuffled = false;
          S.app.refresh();
        }
      } }, "Nullstill"));
    panel.appendChild(el("div", { style: { marginTop: "8px" } }, seg));
    panel.appendChild(actions);
    return panel;
  }

  function paintStats(statsPanel, vis) {
    const c = counts();
    S.u.mount(statsPanel,
      el(".row.wrap", { style: { gap: "26px", alignItems: "center" } },
        el("div", el(".tiny.muted", "Viser"), el("div", { style: { fontWeight: 700, fontSize: "18px" } }, String(vis.length))),
        el("div", el(".tiny", { style: { color: "#1d7a47" } }, "Kunne"), el("div", { style: { fontWeight: 700, fontSize: "18px", color: "#1d7a47" } }, String(c.ok))),
        el("div", el(".tiny", { style: { color: "#b8324b" } }, "Må øve"), el("div", { style: { fontWeight: 700, fontSize: "18px", color: "#b8324b" } }, String(c.no))),
        el("div", el(".tiny.muted", "Ikke vurdert"), el("div", { style: { fontWeight: 700, fontSize: "18px" } }, String(c.unseen)))),
      dualBar(c));
  }
  function dualBar(c) {
    const b = el(".bar", { style: { marginTop: "12px", display: "flex" } });
    const okPct = c.total ? (c.ok / c.total) * 100 : 0;
    const noPct = c.total ? (c.no / c.total) * 100 : 0;
    b.appendChild(el("span", { style: { display: "block", height: "100%", width: okPct + "%", background: "var(--green)" } }));
    b.appendChild(el("span", { style: { display: "block", height: "100%", width: noPct + "%", background: "var(--rose)" } }));
    return b;
  }

  function paintList(listEl, statsPanel) {
    const vis = visible();
    paintStats(statsPanel, vis);
    S.u.clear(listEl);
    if (!vis.length) { listEl.appendChild(sh().empty("🔍", "Ingen spørsmål matcher filteret", "Prøv «Alle spørsmål», eller velg et annet nivå/tema.")); return; }
    const grouped = !shuffled; // kun gruppert på nivå når rekkefølgen ikke er stokket
    let lastLvl = null;
    vis.forEach((q, idx) => {
      if (grouped && q.n !== lastLvl) {
        lastLvl = q.n;
        const info = (D().lvl || {})[q.n] || [`Nivå ${q.n}`, ""];
        listEl.appendChild(el(".part-head", { style: { marginTop: idx ? "26px" : "0" } },
          el(".ptag", info[0]), el(".pname", info[1])));
      }
      listEl.appendChild(questionCard(q, idx + 1, statsPanel, vis.length));
    });
  }

  function questionCard(q, displayNum, statsPanel, visCount) {
    const mark = markOf(q.id);
    const det = el("details.dyb-q" + (mark === "ok" ? ".done" : mark === "no" ? ".again" : ""));
    const sum = document.createElement("summary");
    sum.className = "dyb-qh";
    sum.appendChild(el(".dyb-num", String(displayNum)));
    const qt = el(".dyb-qt", el(".dyb-qtext", q.s),
      el(".dyb-tags", el(".tag", q.k), el(".tag", "Nivå " + q.n)));
    sum.appendChild(qt);
    det.appendChild(sum);

    const ansWrap = el(".dyb-ans");
    const ansBody = el(".dyb-ansin"); ansBody.innerHTML = q.f;
    ansWrap.appendChild(ansBody);

    const self = el(".dyb-self", el("span", "Hvordan gikk det?"));
    const okBtn = el("button.dyb-sb.g" + (mark === "ok" ? ".on" : ""), { onclick: (e) => { e.stopPropagation(); afterMark(q.id, "ok", det, okBtn, noBtn, statsPanel); } }, "Kunne den");
    const noBtn = el("button.dyb-sb.r" + (mark === "no" ? ".on" : ""), { onclick: (e) => { e.stopPropagation(); afterMark(q.id, "no", det, okBtn, noBtn, statsPanel); } }, "Må øve");
    self.appendChild(okBtn); self.appendChild(noBtn);
    ansWrap.appendChild(self);
    det.appendChild(ansWrap);
    return det;
  }

  function afterMark(id, val, det, okBtn, noBtn, statsPanel) {
    setMark(id, val);
    const cur = markOf(id);
    det.classList.remove("done", "again");
    if (cur === "ok") det.classList.add("done"); else if (cur === "no") det.classList.add("again");
    okBtn.classList.toggle("on", cur === "ok");
    noBtn.classList.toggle("on", cur === "no");
    paintStats(statsPanel, visible());
  }

  function shuffleArr(a) { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

  function weakCount() { const m = marks(); return Object.values(m).filter((v) => v === "no").length; }

  S.views.dybde = { render, weakCount };
})(window.SAM3);
